--
-- Table structure for table `ld_approve`
--

DROP TABLE IF EXISTS `ld_approve`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_approve` (
  `id` int(19) NOT NULL,
  `tabid` int(19) NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `description` text,
  `status` int(19) DEFAULT NULL,
  `smcreatorid` int(19) DEFAULT NULL,
  `modifiedby` int(19) DEFAULT NULL,
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `approveallocatetype` int(11) DEFAULT '0',
  `allowediting` int(1) DEFAULT '1',
  `allowantiapproval` int(1) DEFAULT '1',
  `finishedallowedit` varchar(50) DEFAULT NULL,
  `default_on_new` varchar(255) DEFAULT 'no',
  `default_on_submit` varchar(255) DEFAULT 'no',
  `showsubmitremark` varchar(20) DEFAULT 'yes',
  `submitremarkrequire` varchar(20) DEFAULT 'no',
  `showurgent` varchar(20) DEFAULT 'no',
  `allowagainsubmit` varchar(255) DEFAULT NULL,
  `enableexpediting` varchar(20) DEFAULT 'no',
  `finishedfield_allocatetype` varchar(20) DEFAULT NULL,
  `finishedfield_allocateid` text,
  `dataadv` text,
  `dataadvgroup` varchar(255) DEFAULT NULL,
  `isnewapprove` varchar(20) DEFAULT 'no',
  `sequence` int(4) DEFAULT '0',
  `editresetapprove` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

