CREATE TABLE `ld_cashdeposit` (
  `cashdepositid` int(19) NOT NULL,
  `cashdepositdate` date DEFAULT NULL,
  `cashdeposit_no` varchar(200) DEFAULT NULL,
  `Outaccount` int(19) DEFAULT NULL,
  `inaccount` int(19) DEFAULT NULL,
  `cashmoney` decimal(25,8) DEFAULT NULL,
  `Billnumber` varchar(200) DEFAULT NULL,
  `Approveby` int(1) DEFAULT NULL,
  `approvestatus` varchar(255) DEFAULT '未提交',
  `currency_id` int(1) DEFAULT '1',
  `conversion_rate` decimal(25,6) DEFAULT '1.000000',
  `smownerid` int(11) DEFAULT '0',
  `smcreatorid` int(11) DEFAULT '0',
