--
-- Table structure for table `ld_contactrecords`
--

DROP TABLE IF EXISTS `ld_contactrecords`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_contactrecords` (
  `contactrecordID` int(19) NOT NULL DEFAULT '0',
  `Subject` varchar(200) DEFAULT NULL,
  `contactdate` datetime DEFAULT NULL,
  `nextContactDate` datetime DEFAULT NULL,
  `content` text,
  `potentialid` int(19) DEFAULT NULL,
  `accountid` int(19) DEFAULT NULL,
  `contactid` int(19) DEFAULT NULL,
  `contactrecordtype` varchar(200) DEFAULT NULL,
  `salesorderid` int(11) DEFAULT NULL,
  `troubleticketid` int(11) DEFAULT NULL,
  `projectid` int(11) DEFAULT NULL,
  `projecttaskid` int(11) DEFAULT NULL,
  `approvestatus` varchar(200) DEFAULT '未提交',
  `approveby` int(1) DEFAULT NULL,
  `smownerid` int(11) DEFAULT '0',
  `smcreatorid` int(11) DEFAULT '0',
  `modifiedby` int(11) DEFAULT '0',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `description` text,
  `deleted` int(11) DEFAULT '0',
  `currentapprover` varchar(1000) DEFAULT NULL,
  `contactrecord_no` varchar(100) DEFAULT NULL,
  `product_id` int(19) DEFAULT '0',
  `print_times` int(11) DEFAULT '0',
  `approvetime` datetime DEFAULT NULL,
  `longtitude` varchar(200) DEFAULT NULL,
  `latitude` varchar(200) DEFAULT NULL,
  `location_address` varchar(200) DEFAULT NULL,
  `rating` varchar(255) DEFAULT NULL,
  `leads_id` int(19) DEFAULT '0',
  `advance_stage` varchar(100) DEFAULT NULL,
  `approvesubmitter` int(19) DEFAULT '0',
  `approvesubmittedtime` datetime DEFAULT NULL,
  `approveurgent` varchar(10) DEFAULT 'no',
  `approveexpediting` varchar(10) DEFAULT 'no',
  `currentapprovestepid` int(19) DEFAULT '0',
  `sign_longtitude` varchar(200) DEFAULT NULL,
  `sign_latitude` varchar(200) DEFAULT NULL,
  `sign_location_address` varchar(200) DEFAULT NULL,
  `team_memberid` text,
  `tag` varchar(50) DEFAULT NULL,
  `signin_address` varchar(5) DEFAULT NULL,
  `kis_id` varchar(200) DEFAULT NULL,
  `kis_no` varchar(200) DEFAULT NULL,
  `exchtime` datetime DEFAULT NULL,
  `exchmsg` text,
  `latestpushtime` datetime DEFAULT NULL,
  PRIMARY KEY (`contactrecordID`),
  KEY `deleted_createdtime_contactdate` (`contactdate`,`createdtime`,`deleted`),
  KEY `idx_contactrecord_accountid` (`accountid`),
  KEY `accountid` (`accountid`),
  KEY `approvestatus` (`approvestatus`),
  KEY `createdtime` (`createdtime`),
  KEY `modifiedtime` (`modifiedtime`),
  KEY `smcreatorid` (`smcreatorid`),
  KEY `smownerid` (`smownerid`),
  CONSTRAINT `ld_contactrecords_ibfk_1` FOREIGN KEY (`contactrecordID`) REFERENCES `ld_crmentity` (`crmid`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ld_contactrecords`
--

LOCK TABLES `ld_contactrecords` WRITE;
/*!40000 ALTER TABLE `ld_contactrecords` DISABLE KEYS */;
