/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `edu_insertinto_classplane_form02_update` BEFORE UPDATE ON `ld_customform02` FOR EACH ROW BEGIN 

	IF @disable_triggers IS NULL THEN
		IF NEW.approvestatus='已批准' AND OLD.approvestatus<>'已批准' THEN
			INSERT INTO class_plane(crmid,done_status)
			SELECT NEW.customform02id,'no' FROM DUAL
			WHERE NOT EXISTS (SELECT 1 FROM class_plane WHERE crmid=NEW.customform02id AND done_status='no');
		END IF;
	END IF;

END */;;
