--
-- Table structure for table `ld_customreport`
--

DROP TABLE IF EXISTS `ld_customreport`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_customreport` (
  `report_id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `report_name` varchar(255) DEFAULT NULL,
  `report_desc` text,
  `report_type` varchar(255) DEFAULT NULL,
  `parent_id` int(11) DEFAULT NULL,
  `sequence` tinyint(4) DEFAULT NULL,
  `mainmodule` varchar(255) DEFAULT NULL,
  `createdtime` datetime DEFAULT NULL,
  `modify_time` datetime DEFAULT NULL,
  `deleted` tinyint(4) DEFAULT NULL,
  `modify_id` int(11) DEFAULT NULL,
  `limit` int(11) DEFAULT NULL,
  `orderby` varchar(255) DEFAULT NULL,
  `orderby_type` varchar(255) DEFAULT NULL,
  `smcreatorid` int(11) DEFAULT '1',
  `stat_approach` varchar(255) DEFAULT NULL,
  `approveallocatetype` int(11) DEFAULT '0',
  `show_athome` varchar(255) DEFAULT NULL,
  `linkmodulecheck` varchar(50) DEFAULT NULL,
  `can_penetrate` varchar(50) DEFAULT 'no',
  `relatedmodule` varchar(255) DEFAULT NULL,
  `isshow_search` varchar(10) DEFAULT 'yes',
  `isshow_table` varchar(10) DEFAULT 'yes',
  `analysisfolder_id` int(19) DEFAULT '0',
  `sqlstr` longtext,
  `themename` varchar(255) DEFAULT NULL,
  `advance_demand` text,
  `advance_demand_groups` text,
  `primaryname` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`report_id`)
) ENGINE=InnoDB AUTO_INCREMENT=320 DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

