r.signed_data)\n					END\n				) AS group_time,\n				sum(\n					now_s_detail.tax_amount / ld_salesorder.conversion_rate\n				) AS tax_amount\n			FROM\n				ld_salesorder\n			LEFT JOIN ld_salesorderdetail now_s_detail ON now_s_detail.id = ld_salesorder.salesorderid\n			LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.smownerid,\n				\'{userscope}\'\n			)\n			AND (\n				ld_salesorder.signed_data BETWEEN \'{starttime}\'\n				AND \'{endtime}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n		AND now_salesorder.group_time = timetype_table.group_time\n		LEFT JOIN (\n			SELECT\n				pre_s_detail.id AS salesorderid,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 QUARTER\n							)\n						)\n					ELSE\n						YEAR (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 YEAR\n							)\n						)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (signed_data)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					ELSE\n						MONTH (ld_salesorder.signed_data)\n					END\n				) AS group_time,\n				sum(\n					pre_s_detail.tax_amount / ld_salesorder.conversion_rate\n				) AS tax_amount\n			FROM\n				ld_salesorder\n			LEFT JOIN ld_salesorderdetail pre_s_detail ON pre_s_detail.id = ld_salesorder.salesorderid\n			LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.smownerid,\n				\'{userscope}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n		AND pre_salesorder.group_time = timetype_table.group_time\n		GROUP BY\n			timetype_table.group_time\n	) p_num\nGROUP BY\n	p_num.group_time','Default',NULL,NULL,'product_salesorders_amount_y_to_y'),(310,'产品开票金额同比','','sqlchart',NULL,0,NULL,'2023-11-23 16:58:47','2023-11-23 20:28:06',0,1,NULL,NULL,NULL,1,NULL,0,'yes','no','no',NULL,'yes','Bottom',73,'SELECT\n	p_num.where_time,\n	p_num.group_time,\n	(\n		CASE\n		WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n			CONCAT(\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			CONCAT(p_num.group_time, \'月\')\n		END\n	) AS dispaly_group_time,\n	p_num.pre_tax_amount,\n	p_num.now_tax_amount\nFROM\n	(\n		SELECT\n			timetype_table.where_time AS where_time,\n			timetype_table.group_time AS group_time,\n			pre_salesorder.tax_amount AS pre_tax_amount,\n			now_salesorder.tax_amount AS now_tax_amount\n		FROM\n			(\n				SELECT\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (NOW())\n						ELSE\n							YEAR (NOW())\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (date)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (date)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (date)\n						ELSE\n							MONTH (date)\n						END\n					) AS group_time\n				FROM\n					tmp_date a\n				WHERE\n					date LIKE \'%2023%\'\n				GROUP BY\n					group_time\n			) timetype_table\n		LEFT JOIN (\n			SELECT\n				now_s_detail.id AS invoiceid,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (ld_invoice.invoicedate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (ld_invoice.invoicedate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (ld_invoice.invoicedate)\n					ELSE\n						YEAR (ld_invoice.invoicedate)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_invoice.invoicedate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (ld_invoice.invoicedate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_invoice.invoicedate)\n					ELSE\n						MONTH (ld_invoice.invoicedate)\n					END\n				) AS group_time,\n				sum(\n					now_s_detail.tax_amount / ld_invoice.conversion_rate\n				) AS tax_amount\n			FROM\n				ld_invoice\n			LEFT JOIN ld_invoicedetail now_s_detail ON now_s_detail.id = ld_invoice.invoiceid\n			LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_invoice.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_invoice.smownerid,\n				\'{userscope}\'\n			)\n			AND (\n				ld_invoice.invoicedate BETWEEN \'{starttime}\'\n				AND \'{endtime}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n		AND now_salesorder.group_time = timetype_table.group_time\n		LEFT JOIN (\n			SELECT\n				pre_s_detail.id AS invoiceid,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 QUARTER\n							)\n						)\n					ELSE\n						YEAR (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 YEAR\n							)\n						)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_invoice.invoicedate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (ld_invoice.invoicedate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_invoice.invoicedate)\n					ELSE\n						MONTH (ld_invoice.invoicedate)\n					END\n				) AS group_time,\n				sum(\n					pre_s_detail.tax_amount / ld_invoice.conversion_rate\n				) AS tax_amount\n			FROM\n				ld_invoice\n			LEFT JOIN ld_invoicedetail pre_s_detail ON pre_s_detail.id = ld_invoice.invoiceid\n			LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_invoice.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_invoice.smownerid,\n				\'{userscope}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n		AND pre_salesorder.group_time = timetype_table.group_time\n		GROUP BY\n			timetype_table.group_time\n	) p_num\nGROUP BY\n	p_num.group_time','Default',NULL,NULL,'product_invoice_amount_y_to_y'),(311,'产品出库数量同比','','sqlchart',NULL,0,NULL,'2023-11-23 17:29:23','2023-11-23 20:22:42',0,1,NULL,NULL,NULL,1,NULL,0,'yes','no','no',NULL,'yes','Bottom',73,'SELECT\n	p_num.where_time,\n	p_num.group_time,\n	(\n		CASE\n		WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n			CONCAT(\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			CONCAT(p_num.group_time, \'月\')\n		END\n	) AS dispaly_group_time,\n	p_num.pre_num,\n	p_num.now_num\nFROM\n	(\n		SELECT\n			timetype_table.where_time AS where_time,\n			timetype_table.group_time AS group_time,\n			pre_salesorder.quantity AS pre_num,\n			now_salesorder.quantity AS now_num\n		FROM\n			(\n				SELECT\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (NOW())\n						ELSE\n							YEAR (NOW())\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (date)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (date)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (date)\n						ELSE\n							MONTH (date)\n						END\n					) AS group_time\n				FROM\n					tmp_date a\n				WHERE\n					date LIKE \'%2023%\'\n				GROUP BY\n					group_time\n			) timetype_table\n		LEFT JOIN (\n			SELECT\n				now_s_detail.id AS out_id,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (ld_outboundorder.outdate)\n					ELSE\n						YEAR (ld_outboundorder.outdate)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_outboundorder.outdate)\n					ELSE\n						MONTH (ld_outboundorder.outdate)\n					END\n				) AS group_time,\n				sum(now_s_detail.tax_amount) AS tax_amount,\n				sum(now_s_detail.quantity) AS quantity\n			FROM\n				ld_outboundorder\n			LEFT JOIN ld_outboundorderdetail now_s_detail ON now_s_detail.id = ld_outboundorder.out_id\n			LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.smownerid,\n				\'{userscope}\'\n			)\n			AND (\n				ld_outboundorder.outdate BETWEEN \'{starttime}\'\n				AND \'{endtime}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n		AND now_salesorder.group_time = timetype_table.group_time\n		LEFT JOIN (\n			SELECT\n				pre_s_detail.id AS out_id,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 QUARTER\n							)\n						)\n					ELSE\n						YEAR (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 YEAR\n							)\n						)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_outboundorder.outdate)\n					ELSE\n						MONTH (ld_outboundorder.outdate)\n					END\n				) AS group_time,\n				sum(pre_s_detail.tax_amount) AS tax_amount,\n				sum(pre_s_detail.quantity) AS quantity\n			FROM\n				ld_outboundorder\n			LEFT JOIN ld_outboundorderdetail pre_s_detail ON pre_s_detail.id = ld_outboundorder.out_id\n			LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.smownerid,\n				\'{userscope}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n		AND pre_salesorder.group_time = timetype_table.group_time\n		GROUP BY\n			timetype_table.group_time\n	) p_num\nGROUP BY\n	p_num.group_time','Default',NULL,NULL,'product_outboundorder_quantity_y_to_y'),(312,'产品出库金额同比','','sqlchart',NULL,0,NULL,'2023-11-23 17:34:49','2023-11-27 16:49:58',0,1,NULL,NULL,NULL,1,NULL,0,'yes','no','no',NULL,'yes','Bottom',73,'SELECT\n	p_num.where_time,\n	p_num.group_time,\n	(\n		CASE\n		WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n			CONCAT(\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			CONCAT(p_num.group_time, \'月\')\n		END\n	) AS dispaly_group_time,\n	p_num.pre_tax_amount,\n	p_num.now_tax_amount\nFROM\n	(\n		SELECT\n			timetype_table.where_time AS where_time,\n			timetype_table.group_time AS group_time,\n			pre_salesorder.tax_amount AS pre_tax_amount,\n			now_salesorder.tax_amount AS now_tax_amount\n		FROM\n			(\n				SELECT\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (NOW())\n						ELSE\n							YEAR (NOW())\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (date)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (date)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (date)\n						ELSE\n							MONTH (date)\n						END\n					) AS group_time\n				FROM\n					tmp_date a\n				WHERE\n					date LIKE \'%2023%\'\n				GROUP BY\n					group_time\n			) timetype_table\n		LEFT JOIN (\n			SELECT\n				now_s_detail.id AS out_id,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (ld_outboundorder.outdate)\n					ELSE\n						YEAR (ld_outboundorder.outdate)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_outboundorder.outdate)\n					ELSE\n						MONTH (ld_outboundorder.outdate)\n					END\n				) AS group_time,\n				sum(\n					now_s_detail.tax_amount / ld_outboundorder.conversion_rate\n				) AS tax_amount,\n				sum(now_s_detail.quantity) AS quantity\n			FROM\n				ld_outboundorder\n			LEFT JOIN ld_outboundorderdetail now_s_detail ON now_s_detail.id = ld_outboundorder.out_id\n			LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.smownerid,\n				\'{userscope}\'\n			)\n			AND (\n				ld_outboundorder.outdate BETWEEN \'{starttime}\'\n				AND \'{endtime}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n		AND now_salesorder.group_time = timetype_table.group_time\n		LEFT JOIN (\n			SELECT\n				pre_s_detail.id AS out_id,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 QUARTER\n							)\n						)\n					ELSE\n						YEAR (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 YEAR\n							)\n						)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_outboundorder.outdate)\n					ELSE\n						MONTH (ld_outboundorder.outdate)\n					END\n				) AS group_time,\n				sum(\n					pre_s_detail.tax_amount / ld_outboundorder.conversion_rate\n				) AS tax_amount,\n				sum(pre_s_detail.quantity) AS quantity\n			FROM\n				ld_outboundorder\n			LEFT JOIN ld_outboundorderdetail pre_s_detail ON pre_s_detail.id = ld_outboundorder.out_id\n			LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.smownerid,\n				\'{userscope}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n		AND pre_salesorder.group_time = timetype_table.group_time\n		GROUP BY\n			timetype_table.group_time\n	) p_num\nGROUP BY\n	p_num.group_time','Default',NULL,NULL,'product_outboundorder_amount_y_to_y'),(313,'产品签约数量环比','','sqlchart',NULL,0,NULL,'2023-11-23 18:22:09','2023-11-28 19:22:50',0,1,NULL,NULL,NULL,1,NULL,0,'yes','no','no',NULL,'yes','Bottom',73,'SELECT\n	(\n		CASE\n		WHEN \'{timetype}\' = \'季度\' THEN\n			CONCAT(\n				p_num.where_time,\n				\'-\',\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			DATE_FORMAT(\n				STR_TO_DATE(\n					CONCAT(\n						p_num.where_time,\n						\'-\',\n						p_num.group_time\n					),\n					\'%Y-%m\'\n				),\n				\'%Y-%m\'\n			)\n		END\n	) AS dispaly_group_time,\n	sum(p_num.pre_num) AS pre_num,\n	sum(p_num.now_num) AS now_num\nFROM\n	(\n		(\n			SELECT\n				timetype_table.group_time AS group_time,\n				timetype_table.where_time AS where_time,\n				pre_salesorder.quantity AS pre_num,\n				now_salesorder.quantity AS now_num\n			FROM\n				(\n					SELECT\n						(\n							CASE\n							WHEN \'{timetype}\' = \'月\' THEN\n								MONTH (date)\n							WHEN \'{timetype}\' = \'季度\' THEN\n								QUARTER (date)\n							ELSE\n								MONTH (date)\n							END\n						) AS group_time,\n						where_table.where_time AS where_time\n					FROM\n						tmp_date,\n						(\n							SELECT\n								YEAR (\n									DATE_ADD(\n										\'{starttime}\',\n										INTERVAL seq YEAR\n									)\n								) where_time\n							FROM\n								sequence\n							WHERE\n								YEAR (\n									DATE_ADD(\n										\'{starttime}\',\n										INTERVAL seq YEAR\n									)\n								) <= YEAR (\'{endtime}\')\n						) where_table\n					WHERE\n						date LIKE \'%2023%\'\n					GROUP BY\n						where_time,\n						group_time\n				) timetype_table\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					YEAR (ld_salesorder.signed_data) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'季度\' THEN\n							QUARTER (ld_salesorder.signed_data)\n						ELSE\n							MONTH (ld_salesorder.signed_data)\n						END\n					) AS group_time,\n					sum(now_s_detail.quantity) AS quantity\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail now_s_detail ON now_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				AND (\n					ld_salesorder.signed_data BETWEEN \'{starttime}\'\n					AND \'{endtime}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) now_salesorder ON now_salesorder.group_time = timetype_table.group_time\n			AND now_salesorder.where_time = timetype_table.where_time\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'月\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 MONTH\n								)\n							)\n						WHEN \'{timetype}\' = \'季度\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 QUARTER\n								)\n							)\n						ELSE\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 MONTH\n								)\n							)\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'月\' THEN\n							MONTH (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 MONTH\n								)\n							)\n						WHEN \'{timetype}\' = \'季度\' THEN\n							QUARTER (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 QUARTER\n								)\n							)\n						ELSE\n							MONTH (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 MONTH\n								)\n							)\n						END\n					) AS group_time,\n					sum(pre_s_detail.quantity) AS quantity\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail pre_s_detail ON pre_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) pre_salesorder ON pre_salesorder.group_time = timetype_table.group_time\n			AND pre_salesorder.where_time = timetype_table.where_time\n			GROUP BY\n				timetype_table.where_time,\n				timetype_table.group_time\n		)\n		UNION ALL\n			(\n				SELECT\n					timetype_table.group_time AS group_time,\n					timetype_table.where_time AS where_time,\n					pre_servicecontracts.quantity AS pre_num,\n					now_servicecontracts.quantity AS now_num\n				FROM\n					(\n						SELECT\n							(\n								CASE\n								WHEN \'{timetype}\' = \'月\' THEN\n									MONTH (date)\n								WHEN \'{timetype}\' = \'季度\' THEN\n									QUARTER (date)\n								ELSE\n									MONTH (date)\n								END\n							) AS group_time,\n							where_table.where_time AS where_time\n						FROM\n							tmp_date,\n							(\n								SELECT\n									YEAR (\n										DATE_ADD(\n											\'{starttime}\',\n											INTERVAL seq YEAR\n										)\n									) where_time\n								FROM\n									sequence\n								WHERE\n									YEAR (\n										DATE_ADD(\n											\'{starttime}\',\n											INTERVAL seq YEAR\n										)\n									) <= YEAR (\'{endtime}\')\n							) where_table\n						WHERE\n							date LIKE \'%2023%\'\n						GROUP BY\n							where_time,\n							group_time\n					) timetype_table\n				LEFT JOIN (\n					SELECT\n						ld_servicecontracts.servicecontractsid,\n						YEAR (due_date) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'月\' THEN\n								MONTH (due_date)\n							WHEN \'{timetype}\' = \'季度\' THEN\n								QUARTER (due_date)\n							ELSE\n								MONTH (due_date)\n							END\n						) AS group_time,\n						sum(now_sv_detail.quantity) AS quantity\n					FROM\n						ld_servicecontracts\n					LEFT JOIN ld_servicecontractsdetail now_sv_detail ON now_sv_detail.id = ld_servicecontracts.servicecontractsid\n					LEFT JOIN ld_products ON ld_products.productid = now_sv_detail.productid\n					WHERE\n						(\n							ld_products.productname = \'{productname}\'\n							OR \'{productname}\' = \'\'\n						)\n					AND (\n						\'{productcategory}\' = \'\'\n						OR FIND_IN_SET(\n							ld_products.productcategory,\n							\'{productcategory}\'\n						)\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.approvestatus,\n						\'{approvestatus}\'\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.smownerid,\n						\'{userscope}\'\n					)\n					AND (\n						ld_servicecontracts.due_date BETWEEN \'{starttime}\'\n						AND \'{endtime}\'\n					)\n					GROUP BY\n						where_time,\n						group_time\n				) now_servicecontracts ON now_servicecontracts.group_time = timetype_table.group_time\n				AND now_servicecontracts.where_time = timetype_table.where_time\n				LEFT JOIN (\n					SELECT\n						ld_servicecontracts.servicecontractsid,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'月\' THEN\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 MONTH\n									)\n								)\n							WHEN \'{timetype}\' = \'季度\' THEN\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 QUARTER\n									)\n								)\n							ELSE\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 MONTH\n									)\n								)\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'月\' THEN\n								MONTH (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 MONTH\n									)\n								)\n							WHEN \'{timetype}\' = \'季度\' THEN\n								QUARTER (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 QUARTER\n									)\n								)\n							ELSE\n								MONTH (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 MONTH\n									)\n								)\n							END\n						) AS group_time,\n						sum(pre_sv_detail.quantity) AS quantity\n					FROM\n						ld_servicecontracts\n					LEFT JOIN ld_servicecontractsdetail pre_sv_detail ON pre_sv_detail.id = ld_servicecontracts.servicecontractsid\n					LEFT JOIN ld_products ON ld_products.productid = pre_sv_detail.productid\n					WHERE\n						(\n							ld_products.productname = \'{productname}\'\n							OR \'{productname}\' = \'\'\n						)\n					AND (\n						\'{productcategory}\' = \'\'\n						OR FIND_IN_SET(\n				