ted = 0 AND ld_troubletickets.ticketid = {Record.ID}','no'),(203,22,20,0,1,0,1,28,'all','quote_id',5,0,0,0,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(204,22,139,0,0,0,2,28,'all','quote_id',5,0,0,0,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(205,20,141,0,1,0,1,26,'all',NULL,20,0,0,0,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(206,67,21,0,0,0,7,84,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(207,142,26,0,0,0,8,117,'permit',NULL,5,0,0,1,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,'sql','SELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_account\r\nWHERE ld_account.deleted = 0 AND accountid = ?\r\nUNION \r\nSELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_contactdetails\r\nINNER JOIN ld_account ON ld_account.accountid = ld_contactdetails.accountid\r\nWHERE ld_account.deleted = 0 AND ld_contactdetails.contactid = ?\r\nUNION \r\nSELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_contactrecords\r\nINNER JOIN ld_account ON ld_account.accountid = ld_contactrecords.accountid\r\nWHERE ld_account.deleted = 0 AND ld_contactrecords.contactrecordID = ?\r\nUNION \r\nSELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_potential\r\nINNER JOIN ld_account ON ld_account.accountid = ld_potential.accountid\r\nWHERE ld_account.deleted = 0 AND ld_potential.potentialid = ?\r\nUNION \r\nSELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_troubletickets\r\nINNER JOIN ld_account ON ld_account.accountid = ld_troubletickets.accountid\r\nWHERE ld_account.deleted = 0 AND ld_troubletickets.ticketid = ?\r\nUNION \r\nSELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_project\r\nINNER JOIN ld_account ON ld_account.accountid = ld_project.accountid\r\nWHERE ld_account.deleted = 0 AND ld_project.projectid = ?\r\nUNION\r\nSELECT CONCAT(ld_leads.bill_state,ld_leads.bill_city,IFNULL(ld_leads.bill_area,\"\"),ld_leads.bill_street) AS address\r\nFROM ld_leads\r\nWHERE deleted = 0 AND leadsid = ?','no'),(208,48,22,0,NULL,0,1,55,'all',NULL,5,0,0,0,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(209,48,37,0,1,0,2,55,'all',NULL,5,0,0,0,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(210,169,22,0,1,0,1,169,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(211,169,37,0,0,0,2,169,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(212,169,2,1,0,0,3,169,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(213,170,22,0,1,0,1,170,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(214,170,37,0,0,0,2,170,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(215,170,2,1,0,0,3,170,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(216,171,22,0,1,0,1,171,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(217,171,37,0,0,0,2,171,'all',NULL,5,0,0,0,