--

DROP TABLE IF EXISTS `ld_sendcashbill`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_sendcashbill` (
  `sendcashbillid` int(19) NOT NULL,
  `vendorid` int(19) DEFAULT '0',
  `sendcashbill_no` varchar(100) DEFAULT NULL,
  `purchaseorder_id` int(19) DEFAULT '0',
  `cashbilldate` date DEFAULT NULL,
  `crpaymentmethod` varchar(50) DEFAULT NULL,
  `criscashbill` varchar(10) DEFAULT NULL,
  `total` decimal(25,8) DEFAULT NULL,
  `subtotal` decimal(25,8) DEFAULT NULL,
  `nosendpayment` decimal(20,2) DEFAULT '0.00',
  `bankaccountsetid` int(11) DEFAULT NULL,
  `checkoutstatus` varchar(25) DEFAULT '未审核',
  `checker` int(19) DEFAULT NULL,
  `smownerid` int(11) DEFAULT '0',
  `smcreatorid` int(11) DEFAULT '0',
  `modifiedby` int(11) DEFAULT '0',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `deleted` int(11) DEFAULT '0',
  `description` text,
  `currency_id` int(1) DEFAULT '1',
  `conversion_rate` decimal(25,6) DEFAULT '1.000000',
  `currency_symbol` varchar(30) DEFAULT '¥',
  `approveby` int(19) DEFAULT '0',
  `approvestatus` varchar(200) DEFAULT '未提交',
  `currentapprover` varchar(1000) DEFAULT NULL,
  `bank_accountname` varchar(200) DEFAULT NULL,
  `bank_accountnum` varchar(200) DEFAULT NULL,
  `bank_opening` varchar(200) DEFAULT NULL,
  `corporatename` varchar(200) DEFAULT NULL,
  `print_times` int(11) DEFAULT '0',
  `approvetime` datetime DEFAULT NULL,
  `source_list` text,
  `entitytype` varchar(100) DEFAULT NULL,
  `advance_stage` varchar(100) DEFAULT NULL,
  `approvesubmitter` int(19) DEFAULT '0',
  `approvesubmittedtime` datetime DEFAULT NULL,
  `approveurgent` varchar(10) DEFAULT 'no',
  `approveexpediting` varchar(10) DEFAULT 'no',
  `currentapprovestepid` int(19) DEFAULT '0',
  `team_memberid` text,
  `tag` varchar(50) DEFAULT NULL,
  `kis_id` varchar(200) DEFAULT NULL,
  `kis_no` varchar(200) DEFAULT NULL,
  `exchtime` datetime DEFAULT NULL,
  `exchmsg` text,
  `latestpushtime` datetime DEFAULT NULL,
  `discount_type` int(1) DEFAULT '0',
  `discount_percent` decimal(25,2) DEFAULT '0.00',
  `discount_amount` decimal(25,2) DEFAULT '0.00',
  `adjustment` decimal(25,2) DEFAULT '0.00',
  `product_licence_price` decimal(25,2) DEFAULT '0.00',
  `cumulative_benefits` decimal(25,2) DEFAULT '0.00',
  PRIMARY KEY (`sendcashbillid`),
  KEY `idx_crpaymentmethod_sendcashbill` (`crpaymentmethod`) USING BTREE,
  KEY `idx_vendorid_sendcashbill` (`vendorid`) USING BTREE,
  KEY `idx_purchaseorder_sendcashbill` (`purchaseorder_id`) USING BTREE,
  KEY `approvestatus` (`approvestatus`),
  KEY `createdtime` (`createdtime`),
  KEY `modifiedtime` (`modifiedtime`),
