--
-- Table structure for table `ld_tab`
--

DROP TABLE IF EXISTS `ld_tab`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_tab` (
  `tabid` int(19) NOT NULL DEFAULT '0',
  `name` varchar(50) DEFAULT NULL,
  `presence` int(19) NOT NULL DEFAULT '1',
  `tabsequence` int(10) DEFAULT NULL,
  `tablabel` varchar(50) DEFAULT NULL,
  `modifiedby` int(19) DEFAULT NULL,
  `modifiedtime` int(19) DEFAULT NULL,
  `customized` int(19) DEFAULT NULL,
  `ownedby` int(19) DEFAULT NULL,
  `isentitytype` int(11) NOT NULL DEFAULT '1',
  `version` varchar(10) DEFAULT NULL,
  `parent` varchar(30) DEFAULT NULL,
  `printtab` int(11) DEFAULT '0',
  `Proportion` int(11) DEFAULT '0',
  `description` varchar(100) DEFAULT NULL,
  `mobilepresence` varchar(255) DEFAULT NULL,
  `isduplicate` varchar(20) DEFAULT NULL,
  `fristvisit` text,
  `main_tablename` varchar(100) DEFAULT NULL,
  `custom_tablename` varchar(100) DEFAULT NULL,
  `primary_key` varchar(100) DEFAULT NULL,
  `quicksubmit` varchar(20) DEFAULT 'yes',
  `againsubmit` varchar(20) DEFAULT 'no',
  `default_icon` varchar(255) DEFAULT NULL,
  `active_icon` varchar(255) DEFAULT NULL,
  `detail_issticky` tinyint(2) DEFAULT '3',
  `showdisabledapprove` varchar(20) DEFAULT 'no',
  `mobiledetailinfoshowtype` char(10) DEFAULT NULL,
  PRIMARY KEY (`tabid`),
  UNIQUE KEY `tab_name_idx` (`name`) USING BTREE,
  UNIQUE KEY `multi1_idx` (`tabid`,`presence`,`tabsequence`,`tablabel`) USING BTREE,
  KEY `tab_modifiedby_idx` (`modifiedby`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

