  `approve_demand` varchar(50) DEFAULT NULL,
  `maxrowsshow` int(11) DEFAULT '0',
  `bigtype` varchar(50) DEFAULT NULL,
  `savedatabase` varchar(50) DEFAULT 'yes',
  `fieldvaluecolor` varchar(20) DEFAULT NULL,
  `fieldplaceholder` varchar(300) DEFAULT NULL,
  `effectivecondition` text,
  `parentbigtype` varchar(50) DEFAULT NULL,
  `sourcemodule` varchar(50) DEFAULT NULL,
  `mobiledetailshow` char(10) DEFAULT NULL,
  `relatedmodulefield` varchar(20) DEFAULT 'no',
