  `start` decimal(10,2) DEFAULT NULL COMMENT '开始计算区间',
  `end` decimal(10,2) DEFAULT NULL COMMENT '结束计算区间',
  `unit` varchar(10) DEFAULT NULL COMMENT '单位 %或者万元',
  `commission_rate` decimal(10,2) DEFAULT NULL COMMENT '提成',
  `commission_unit` varchar(10) DEFAULT NULL COMMENT '提成单位 % 或者元等其他单位 目前只用到%',
  `currency_id` int(11) DEFAULT NULL COMMENT '币种',
  `order` tinyint(4) DEFAULT NULL COMMENT '排序',
  `bytype` varchar(50) DEFAULT NULL,
  `is_on` varchar(10) DEFAULT NULL COMMENT '是否启用 yes no',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

