/*!50003 DROP FUNCTION IF EXISTS `getpinyin` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  FUNCTION `getpinyin`(NAME VARCHAR(255) CHARSET GBK) RETURNS varchar(255) CHARSET gbk
BEGIN

	DECLARE mycode INT(19); 
	DECLARE tmp_lcode VARCHAR(2) CHARSET GBK; 
	DECLARE lcode INT(19); 
	DECLARE tmp_rcode VARCHAR(2) CHARSET GBK;
	DECLARE rcode INT(19); 
	DECLARE mypy VARCHAR(255) CHARSET GBK DEFAULT ''; 
	DECLARE lp INT(19); 

	
	SET mycode = 0 ;
	SET lp = 1 ;
	SET NAME = HEX(NAME);

	WHILE lp < length(NAME) DO
		SET tmp_lcode = SUBSTRING(NAME,lp,2);
		SET lcode = CAST(ASCII(UNHEX(tmp_lcode)) AS UNSIGNED);
		SET tmp_rcode = SUBSTRING(NAME,lp+2,2);
		SET rcode = CAST(ASCII(UNHEX(tmp_rcode)) AS UNSIGNED);

		IF lcode > 128 THEN
			SET mycode = 65536 - lcode * 256 - rcode ; 
			SELECT
				CONCAT(mypy,pin_yin_) INTO mypy
			FROM base_pinyin
			WHERE code_ >= abs(mycode)
			ORDER BY code_ ASC
			LIMIT 1 ;

			SET lp = lp + 4 ;
		ELSE
			SET mypy = CONCAT(mypy,CHAR(CAST(ASCII(UNHEX(SUBSTRING(NAME, lp, 2))) AS UNSIGNED)));
			SET lp = lp + 2 ;
		END IF ;
	END WHILE; 
	RETURN lower(mypy) ;
END ;;
DELIMITER ;
