/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `DelColumn` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `DelColumn`(
	tablename varchar(50),
	columnname varchar(50)
)
begin

	select database() into @tableschema;

	set tablename=lower(tablename);
	set @colName='';
	SET @tsql=CONCAT('select  IFNULL(column_name, '''') into @colName  from information_schema.columns where  TABLE_SCHEMA =','''',@tableschema,'''','  and  table_name= ','''',tablename,'''',' and COLUMN_NAME=','''',columnname,'''');

	prepare stmt from @tsql;
	execute stmt;

	set @coldel=IFNULL(@colName,'-1');

	IF @coldel <> '-1'  and  @coldel=columnname THEN

		set @alterColumn=CONCAT(' alter table ',tablename, ' drop ',columnname);
		prepare stalter from @altercolumn;
		execute stalter;
		deallocate prepare stalter;
	END IF;

	deallocate prepare stmt;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `DelPrikey` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `DelPrikey`(
tablename varchar(50)
)
begin

select database() into @tableschema;  
SET @sql1=CONCAT("select count(column_key) into @del from information_schema.columns where table_schema='",@tableschema,"' and table_name='",tablename,"' and column_key='PRI'");
SET @sql2=CONCAT('alter table ',tablename,' drop primary key');

PREPARE statement_name FROM @sql1; 
EXECUTE statement_name;
DEALLOCATE PREPARE statement_name;

IF @del>0 THEN 
	PREPARE statement_name FROM @sql2; 
	EXECUTE statement_name;
	DEALLOCATE PREPARE statement_name;
END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Del_ForeignKey` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `Del_ForeignKey`(
	tmp_tablename varchar(100),
	tmp_fkeyname varchar(100)
)
BEGIN

	IF EXISTS (SELECT 1 FROM information_schema.KEY_COLUMN_USAGE WHERE CONSTRAINT_NAME=tmp_fkeyname AND TABLE_NAME=tmp_tablename AND TABLE_SCHEMA=DATABASE()) THEN
		SET @execsql=CONCAT(' ALTER TABLE ',tmp_tablename, ' DROP FOREIGN KEY ',tmp_fkeyname);
		PREPARE stmt_execsql FROM @execsql; 
		EXECUTE stmt_execsql;
		DEALLOCATE PREPARE stmt_execsql;
	END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Del_TableIndex` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `Del_TableIndex`(
	tmp_tablename varchar(100),
	tmp_indexname varchar(100)
)
BEGIN  

	IF EXISTS (SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=tmp_tablename AND index_name=tmp_indexname) THEN  
		SET @execsql=CONCAT(' DROP INDEX ',tmp_indexname,' ON ',tmp_tablename);
		PREPARE stmt_execsql FROM @execsql; 
		EXECUTE stmt_execsql;
		DEALLOCATE PREPARE stmt_execsql;
	END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `edu_add_classplane_byapply` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `edu_add_classplane_byapply`(
)
BEGIN

	SELECT 0,0 INTO @edu_classid,@edu_classcrmid;
	SELECT id,crmid INTO @edu_classid,@edu_classcrmid FROM class_plane WHERE done_status='no' ORDER BY id LIMIT 1;
	IF @edu_classid>0 AND @edu_classcrmid>0 THEN
		UPDATE class_plane SET done_status='yes',done_starttime=NOW() WHERE id=@edu_classid;
		CALL edu_add_classplane_byrelatedcrmid(@edu_classcrmid);
		UPDATE class_plane SET done_endtime=NOW() WHERE id=@edu_classid;
	ELSE
		UPDATE class_plane SET done_status='yes',done_starttime=NOW() WHERE id=@edu_classid;
	END IF;	

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `edu_add_classplane_byrelatedcrmid` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `edu_add_classplane_byrelatedcrmid`(
	tmp_apply_id INT(19)
)
BEGIN

	DECLARE tmp_xueyuan_id INT(19) DEFAULT 0;
	DECLARE tmp_course_id INT(19) DEFAULT 0;
	DECLARE tmp_order_id INT(19) DEFAULT 0;
	DECLARE tmp_owner_id INT(19) DEFAULT 0;
	DECLARE tmp_activityid INT(19) DEFAULT 0;

	DECLARE tmp_ke_cnt INT(19) DEFAULT 0;

	DECLARE MYCUSOR CURSOR FOR 
		SELECT
			a.xueyuan_id,
			a.course_id,
			a.order_id,
			a.owner_id,
			a.activityid,
			a.ke_cnt
		FROM (
			SELECT
				(SELECT accountid FROM ld_customform02 WHERE customform02id=tmp_apply_id) AS xueyuan_id,
				(SELECT product_id FROM ld_customform02 WHERE customform02id=tmp_apply_id) AS course_id,
				(SELECT salesorderid FROM ld_customform02 WHERE customform02id=tmp_apply_id) AS order_id,
				(SELECT smownerid FROM ld_customform02 WHERE customform02id=tmp_apply_id) AS owner_id,
				a.activityid,
				(
					SELECT 
						a.quantity
					FROM ld_salesorderdetail a
					LEFT JOIN ld_customform02 b ON b.salesorderid=a.id 
					LEFT JOIN ld_customform01 c On c.customform01id=b.customform01_id AND a.productid=c.product_id
					WHERE b.customform02id=tmp_apply_id LIMIT 1
				) AS ke_cnt,
				(SELECT IF(IFNULL(cf_3439,'')='',1,REPLACE(cf_3439,'1:','')) FROM ld_customform01scf WHERE customform01id=a.customform01_id) AS ke_rate
			FROM ld_activity a
			WHERE a.deleted=0
				AND a.customform01_id=(SELECT customform01_id FROM ld_customform02 WHERE customform02id=tmp_apply_id)
				AND a.due_date>=(SELECT cf_3443 FROM ld_customform02scf WHERE customform02id=tmp_apply_id)
		) a,
		(SELECT @i:=0) b
		WHERE 1=1
			AND (@i:=@i+1)<=CEIL(a.ke_cnt/a.ke_rate);

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_activityid = NULL;

	OPEN MYCUSOR; 
	FETCH MYCUSOR INTO tmp_xueyuan_id,tmp_course_id,tmp_order_id,tmp_owner_id,tmp_activityid,tmp_ke_cnt;
	WHILE(tmp_activityid IS NOT NULL) DO
		
		SET @add_maxcrmid=(SELECT MAX(crmid) FROM ld_crmentity);
		INSERT INTO ld_crmentity(crmid,setype)
		SELECT @add_maxcrmid+1,'CustomForm03';

		UPDATE ld_crmentity_seq SET id=(SELECT MAX(crmid) FROM ld_crmentity);

		INSERT INTO ld_customform03(
			customform03id,
			customform03_no,

			customform02_id,
			accountid,
			product_id,
			salesorderid,
			calendar_id,

			smownerid,					
			smcreatorid,				
			modifiedby,					
			createdtime,				
			modifiedtime
		)
		SELECT
			@add_maxcrmid+1,
			(SELECT CONCAT(prefix,cur_id) FROM ld_modentity_num WHERE semodule='CustomForm03' AND active=1),

			tmp_apply_id,
			tmp_xueyuan_id,
			tmp_course_id,
			tmp_order_id,
			tmp_activityid,

			tmp_owner_id,
			tmp_owner_id,
			tmp_owner_id,
			NOW(),
			NOW();

		INSERT INTO ld_customform03scf(customform03id,cf_3447) SELECT @add_maxcrmid+1,tmp_ke_cnt;
		UPDATE ld_modentity_num SET cur_id=cur_id+1 WHERE semodule='CustomForm03' AND active=1;

		FETCH MYCUSOR INTO tmp_xueyuan_id,tmp_course_id,tmp_order_id,tmp_owner_id,tmp_activityid,tmp_ke_cnt;
	END WHILE;
	CLOSE MYCUSOR;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
