/*!50003 DROP PROCEDURE IF EXISTS `edu_add_courseplane_byapply` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `edu_add_courseplane_byapply`(
)
BEGIN

	SELECT 0,0 INTO @edu_thisid,@edu_crmid;
	SELECT id,crmid INTO @edu_thisid,@edu_crmid FROM course_plane WHERE done_status='no' ORDER BY id LIMIT 1;
	IF @edu_crmid>0 AND @edu_thisid>0 THEN
		UPDATE course_plane SET done_status='yes',done_starttime=NOW() WHERE id=@edu_thisid;
		CALL edu_add_courseplane_byrelatedcrmid(@edu_crmid);
		UPDATE course_plane SET done_endtime=NOW() WHERE id=@edu_thisid;
	ELSE
		UPDATE course_plane SET done_status='yes',done_starttime=NOW() WHERE id=@edu_thisid;
	END IF;	

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `edu_add_courseplane_bycourseplaninfo` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `edu_add_courseplane_bycourseplaninfo`(
	tmp_apply_id INT(19),
	tmp_course_id INT(19),
	tmp_room_id INT(19),
	tmp_teacher_id INT(19),
	tmp_smownerid INT(19),
	tmp_zhuti VARCHAR(255),
	tmp_course_type VARCHAR(100),
	tmp_weekday VARCHAR(255),
	tmp_startdate DATE,
	tmp_enddate DATE,
	tmp_starttime DATETIME,
	tmp_endtime DATETIME,
	tmp_course_cnt INT(19)
)
BEGIN
	
	DECLARE tmp_mycnt  INT DEFAULT 1;
	DECLARE tmp_mydate DATE DEFAULT NULL;

	IF tmp_enddate>=CURDATE() AND tmp_course_cnt>0 THEN
		WHILE (tmp_mycnt<=tmp_course_cnt AND tmp_mydate<=tmp_endtime) DO
				SELECT 1;
				SET tmp_mycnt = tmp_mycnt + 1;
		END WHILE;
	END IF;


end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `edu_add_courseplane_byrelatedcrmid` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `edu_add_courseplane_byrelatedcrmid`(
	tmp_apply_id INT(19)
)
BEGIN

	DECLARE tmp_i INT(19) DEFAULT 0;

	DECLARE tmp_zhuti VARCHAR(255) DEFAULT NULL;
	DECLARE tmp_starttime DATETIME DEFAULT NULL;
	DECLARE tmp_endtime DATETIME DEFAULT NULL;
	DECLARE tmp_coursetype VARCHAR(100) DEFAULT NULL;

	DECLARE tmp_courseid INT(19) DEFAULT 0;
	DECLARE tmp_roomid INT(19) DEFAULT 0;
	DECLARE tmp_teacherid INT(19) DEFAULT 0;
	DECLARE tmp_ownerid INT(19) DEFAULT 0;

	DECLARE MYCUSOR CURSOR FOR 
		SELECT
			(SELECT cf_3436 FROM ld_customform01scf WHERE customform01id=tmp_apply_id) AS zhuti,
			CONCAT(mydate,' ',(SELECT IFNULL(LEFT(cf_3430,LOCATE('至',cf_3430)-1),'00:00') FROM ld_customform01scf WHERE customform01id=tmp_apply_id),':00') AS starttime,
			CONCAT(mydate,' ',(SELECT IFNULL(RIGHT(cf_3430,CHAR_LENGTH(cf_3430)-LOCATE('至',cf_3430)),'00:00') FROM ld_customform01scf WHERE customform01id=tmp_apply_id),':00') AS endtime,
			(SELECT cf_3599 FROM ld_customform01scf WHERE customform01id=tmp_apply_id) AS course_type,
			(SELECT product_id FROM ld_customform01 WHERE customform01id=tmp_apply_id) AS course_id,
			(SELECT projecttaskid FROM ld_customform01 WHERE customform01id=tmp_apply_id) AS room_id,
			(SELECT projectmilestone_id FROM ld_customform01 WHERE customform01id=tmp_apply_id) AS teacher_id,
			(SELECT smownerid FROM ld_customform01 WHERE customform01id=tmp_apply_id) AS owner_id
		FROM (
			SELECT
				date AS mydate,
				CASE 
					WHEN WEEKDAY(date)=0 THEN '周一'
					WHEN WEEKDAY(date)=1 THEN '周二'
					WHEN WEEKDAY(date)=2 THEN '周三'
					WHEN WEEKDAY(date)=3 THEN '周四'
					WHEN WEEKDAY(date)=4 THEN '周五'
					WHEN WEEKDAY(date)=5 THEN '周六'
					WHEN WEEKDAY(date)=6 THEN '周日'
				END AS week_day
			FROM tmp_date
			WHERE date BETWEEN (SELECT cf_3426 FROM ld_customform01scf WHERE customform01id=tmp_apply_id) AND (SELECT cf_3427 FROM ld_customform01scf WHERE customform01id=tmp_apply_id)
		) a,
		(SELECT @i:=0) b
		WHERE FIND_IN_SET(week_day,(SELECT REPLACE(cf_3432,' |##| ',',') FROM ld_customform01scf WHERE customform01id=tmp_apply_id))
			AND (@i:=@i+1)<=(SELECT cf_3433 FROM ld_customform01scf WHERE customform01id=tmp_apply_id)/(SELECT IF(IFNULL(cf_3439,'')='',1,REPLACE(cf_3439,'1:','')) FROM ld_customform01scf WHERE customform01id=tmp_apply_id);

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_ownerid = NULL;

	OPEN MYCUSOR; 
	FETCH MYCUSOR INTO tmp_zhuti,tmp_starttime,tmp_endtime,tmp_coursetype,tmp_courseid,tmp_roomid,tmp_teacherid,tmp_ownerid;
	WHILE(tmp_ownerid IS NOT NULL) DO
		
		SET @add_maxcrmid=(SELECT MAX(crmid) FROM ld_crmentity);
		INSERT INTO ld_crmentity(crmid,setype)
		SELECT @add_maxcrmid+1,'Calendar';

		UPDATE ld_crmentity_seq SET id=(SELECT MAX(crmid) FROM ld_crmentity);

		INSERT INTO ld_activity(
			activityid,
			`subject`,
			activitytype,
			date_start,
			due_date,

			customform01_id,			
			projecttaskid,				
			projectmilestone_id,	
			product_id,						

			smownerid,					
			smcreatorid,				
			modifiedby,					
			createdtime,				
			modifiedtime
		)
		SELECT
			@add_maxcrmid+1,
			tmp_zhuti,
			tmp_coursetype,
			tmp_starttime,
			tmp_endtime,

			tmp_apply_id,		
			tmp_roomid,			
			tmp_teacherid,	
			tmp_courseid,		

			tmp_ownerid,
			tmp_ownerid,
			tmp_ownerid,
			NOW(),
			NOW();

		INSERT INTO ld_activitycf(activityid) SELECT @add_maxcrmid+1;
	
		FETCH MYCUSOR INTO tmp_zhuti,tmp_starttime,tmp_endtime,tmp_coursetype,tmp_courseid,tmp_roomid,tmp_teacherid,tmp_ownerid;
	END WHILE;
	CLOSE MYCUSOR;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
