DELIMITER ;;
CREATE  PROCEDURE `ldcrm_add_holiday`(
	tmp_name VARCHAR(100),
	tmp_date DATE,
	tmp_type VARCHAR(10)
)
BEGIN


		SET @autoadd_module='Holiday';
		SET @tmp_date=tmp_date;

		SET @tmp_title=CONCAT(DATE_FORMAT(tmp_date,'%Y年'),tmp_name,IF(tmp_type='休','放','补'),'假');
		
		IF NOT EXISTS (SELECT 1 FROM ld_holiday WHERE deleted=0 AND holiday_date=@tmp_date) THEN
			SET @autoadd_maxcrmid=(SELECT MAX(crmid) FROM ld_crmentity);
			INSERT INTO ld_crmentity(crmid,setype)
			SELECT @autoadd_maxcrmid+1,@autoadd_module;
			UPDATE ld_crmentity_seq SET id=(SELECT MAX(crmid) FROM ld_crmentity);

			INSERT INTO ld_holiday(
				holidayid,
				holidayno,

				
				holiday_title,
				holiday_name,
				holiday_date,
				wheatherholidays,
				holiday_type,
				deleted,
				
				smownerid,					
				smcreatorid,				
				modifiedby,					
				createdtime,				
				modifiedtime
			)
			SELECT
				@autoadd_maxcrmid+1,
				(SELECT CONCAT(prefix,cur_id) FROM ld_modentity_num WHERE semodule=@autoadd_module AND active=1),

				@tmp_title,
				tmp_name,
				tmp_date,
				tmp_type,
				'法定节假日',
				0,
				
				1,					
				1,				
				1,					
				NOW(),				
				NOW();
		
			UPDATE ld_modentity_num SET cur_id=cur_id+1 WHERE semodule=@autoadd_module AND active=1;

			INSERT INTO ld_holidayscf(holidayid) SELECT @autoadd_maxcrmid+1;

	END IF;
			
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_add_producttotal_and_cumulativebenefits` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_add_producttotal_and_cumulativebenefits`()
BEGIN

    DECLARE tmptabid INT(11) DEFAULT 0;
    DECLARE tmpsourcemodule VARCHAR(50) DEFAULT '';
    DECLARE tmpuitype INT(10) DEFAULT 0;
    DECLARE tmptypeofdata VARCHAR(20) DEFAULT 'N~O~25,2';
    DECLARE tmptablename VARCHAR(50) DEFAULT 'ld_products';

    DECLARE MYCUSOR CURSOR FOR SELECT tabid,sourcemodule,uitype,typeofdata,tablename FROM ld_producttoolfield WHERE columnname = 'total';

    DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmptabid = NULL;

    OPEN MYCUSOR;
    FETCH MYCUSOR INTO tmptabid,tmpsourcemodule,tmpuitype,tmptypeofdata,tmptablename;
    WHILE(tmptabid IS NOT NULL) DO
			SET @disable_triggers=1;
            SET @producttoolfieldid=(SELECT MAX(producttoolfieldid)+1 FROM ld_producttoolfield);
            SET @columnname = 'product_licence_price';
            SET @trantable='ld_producttoolfield';
            SET @allowhide = 'no';
            SET @fieldlabel = '产品总价';
            SET @zh='产品总价';
            SET @en='Product licence price';
            SET @bigtype='currency';
            SET @parentbigtype='';
            SET @newline=1;
            SET @edit_permission=1;
            SELECT IFNULL(MAX(sequence),1) INTO @sequence FROM ld_producttoolfield where tabid=tmptabid;
            INSERT INTO ld_producttoolfield(producttoolfieldid,columnname,allowhide,fieldlabel,defaultvalue,presence,uitype,typeofdata,sequence,tabid,tablename,width,edit_permission,input_type, fieldid,newline,defaultcolumn,is_checkimportfield,nullfield,referencemodule,datarange,approve_demand,maxrowsshow,bigtype,savedatabase,parentbigtype,sourcemodule)
            SELECT @producttoolfieldid,@columnname,@allowhide,@fieldlabel,NULL,0,tmpuitype,tmptypeofdata,@sequence+1,tmptabid,tmptablename,45,@edit_permission,0,0,@newline,2,0,0,'','','',0,@bigtype,'yes',@parentbigtype,tmpsourcemodule FROM DUAL
            WHERE NOT EXISTS (SELECT 1 FROM ld_producttoolfield WHERE tabid=tmptabid AND columnname=@columnname AND tablename=tmptablename AND IFNULL(sourcemodule,1) = IFNULL(tmpsourcemodule,1) );

            SELECT producttoolfieldid INTO @relatedid FROM ld_producttoolfield WHERE tabid=tmptabid AND columnname=@columnname AND IFNULL(sourcemodule,1) = IFNULL(tmpsourcemodule,1) LIMIT 1;
            INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
            SELECT 'zh',@trantable,tmptabid,@relatedid,@zh FROM DUAL
            WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE languagetype = 'zh' AND tabid=tmptabid AND relateid=@relatedid AND trantable=@trantable);
            INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
            SELECT 'en',@trantable,tmptabid,@relatedid,@en FROM DUAL
            WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE languagetype = 'en' AND tabid=tmptabid AND relateid=@relatedid AND trantable=@trantable);

            CALL AddColumn (tmptablename,@columnname,'decimal','(25,8)',0);

            SET @exec_sql = CONCAT('UPDATE ',tmptablename,' SET ', @columnname, ' = total WHERE (total <> 0 OR total IS NOT NULL) AND ', @columnname, ' = 0');
            PREPARE mystmt FROM @exec_sql;
            EXECUTE mystmt;
            DEALLOCATE PREPARE mystmt;

            SET @producttoolfieldid=(SELECT MAX(producttoolfieldid)+1 FROM ld_producttoolfield);
            SET @columnname = 'cumulative_benefits';
            SET @trantable='ld_producttoolfield';
            SET @allowhide = 'no';
            SET @fieldlabel = '累计优惠';
            SET @zh='累计优惠';
            SET @en='Cumulative Benefits';
            SET @bigtype='currency';
            SET @parentbigtype='';
            SET @newline=1;
            SET @edit_permission=1;
            SELECT IFNULL(MAX(sequence),1) INTO @sequence FROM ld_producttoolfield where tabid=tmptabid;
            INSERT INTO ld_producttoolfield(producttoolfieldid,columnname,allowhide,fieldlabel,defaultvalue,presence,uitype,typeofdata,sequence,tabid,tablename,width,edit_permission,input_type, fieldid,newline,defaultcolumn,is_checkimportfield,nullfield,referencemodule,datarange,approve_demand,maxrowsshow,bigtype,savedatabase,parentbigtype,sourcemodule)
            SELECT @producttoolfieldid,@columnname,@allowhide,@fieldlabel,NULL,0,tmpuitype,tmptypeofdata,@sequence+1,tmptabid,tmptablename,45,@edit_permission,0,0,@newline,2,0,0,'','','',0,@bigtype,'yes',@parentbigtype,tmpsourcemodule FROM DUAL
            WHERE NOT EXISTS (SELECT 1 FROM ld_producttoolfield WHERE tabid=tmptabid AND columnname=@columnname AND tablename=tmptablename AND IFNULL(sourcemodule,1) = IFNULL(tmpsourcemodule,1) );

            SELECT producttoolfieldid INTO @relatedid FROM ld_producttoolfield WHERE tabid=tmptabid AND columnname=@columnname AND IFNULL(sourcemodule,1) = IFNULL(tmpsourcemodule,1) LIMIT 1;
            INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
            SELECT 'zh',@trantable,tmptabid,@relatedid,@zh FROM DUAL
            WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE languagetype = 'zh' AND tabid=tmptabid AND relateid=@relatedid AND trantable=@trantable);
            INSERT INTO ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
            SELECT 'en',@trantable,tmptabid,@relatedid,@en FROM DUAL
            WHERE NOT EXISTS (SELECT 1 FROM ld_tranlabel WHERE languagetype = 'en' AND tabid=tmptabid AND relateid=@relatedid AND trantable=@trantable);

            CALL AddColumn (tmptablename,@columnname,'decimal','(25,8)',0);

            UPDATE ld_producttoolfield a
                LEFT JOIN ld_producttoolfield b ON b.tabid = a.tabid AND b.tablename = a.tablename AND IFNULL(b.sourcemodule,1) = IFNULL(a.sourcemodule,1) AND b.columnname = 'cumulative_benefits'
            SET a.sequence = (b.sequence+1) WHERE a.columnname='total';

            UPDATE ld_producttoolfield_seq SET ld_producttoolfield_seq.id=(SELECT MAX(producttoolfieldid) FROM ld_producttoolfield);
			SET @disable_triggers=NULL;
            FETCH MYCUSOR INTO tmptabid,tmpsourcemodule,tmpuitype,tmptypeofdata,tmptablename;
        END WHILE;

    CLOSE MYCUSOR;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_add_profile_for_bireportscreen` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_add_profile_for_bireportscreen`()
BEGIN

    DECLARE tmp_profileid INT(19) DEFAULT 0;

    DECLARE MYCUSOR CURSOR FOR SELECT profileid FROM ld_profile WHERE profileid>0;

    DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_profileid = NULL;

    SET @tabid=(select tabid from ld_tab  where name='BIReportScreen');

    set @operation = (SELECT actionid from ld_actionmapping where actionname = 'index');

    IF NOT EXISTS (SELECT 1 FROM ld_profileallpermission WHERE tabid=@tabid) THEN
        INSERT INTO ld_profileallpermission(tabid,operation,sequence) VALUES (@tabid,@operation,0);
    END IF;

        IF NOT EXISTS (SELECT 1 FROM ld_profile2standardpermissions WHERE tabid=@tabid) THEN
            OPEN MYCUSOR;
            FETCH MYCUSOR INTO tmp_profileid;
            WHILE(tmp_profileid IS NOT NULL) DO
                    SET @profileid=tmp_profileid;
                    INSERT INTO ld_profile2standardpermissions(profileid,tabid,operation,permissions,sequence)
                    SELECT
                        @profileid AS profileid,
                        @tabid AS tabid,
                        @operation,
                        0,
                        0
                    FROM ld_profile2standardpermissions a
                             LEFT JOIN ld_tab b ON b.tabid=a.tabid
                    WHERE a.profileid=@profileid
                      AND a.operation=@operation
                    LIMIT 1;

                    SET @i=0;
                    UPDATE ld_profile2standardpermissions SET sequence=(@i:=@i+1) WHERE tabid=@tabid AND profileid=@profileid ORDER BY sequence;

                    IF NOT EXISTS (SELECT 1 FROM ld_profile2tab WHERE tabid=@tabid AND profileid=@profileid) THEN
                        INSERT INTO ld_profile2tab(profileid,tabid,permissions)
                        SELECT profileid,@tabid,IF(MIN(permissions)=0,1,0) FROM ld_profile2standardpermissions WHERE tabid=@tabid AND profileid=@profileid;
                    END IF;

                    IF NOT EXISTS (SELECT 1 FROM ld_profile2standardpermissions WHERE tabid=@tabid AND profileid=@profileid AND permissions=0) THEN
                        UPDATE ld_profile2standardpermissions SET permissions=1 WHERE tabid=@tabid AND profileid=@profileid AND operation=0;
                    END IF;

                    FETCH MYCUSOR INTO tmp_profileid;
                END WHILE;
            CLOSE MYCUSOR;
        END IF;
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
