				0
			FROM ld_profile2standardpermissions a
			LEFT JOIN ld_tab b ON b.tabid=a.tabid
			WHERE b.`name` IN ('Customreport','OftenUseReport','CustomEcharts','CustomTables','Comprehensivereport')
