CREATE  PROCEDURE `ldcrm_add_sms`(
	tmp_mobile VARCHAR(50),
	tmp_jieshouren VARCHAR(255),
	tmp_content TEXT,
	tmp_sendtime DATETIME,
	tmp_sender VARCHAR(100),
	tmp_relatedid INT(19)
)
BEGIN

	SET @cnt=(SELECT COUNT(SubmitTime) FROM ld_smssend WHERE DATE_FORMAT(SubmitTime,'%Y-%m-%d')=CURDATE());

	INSERT INTO ld_smssend(
		TaskID,
		BatchNo,
		CalledNumber,
		SmsContent,
		SubmitTime,
		CreateTime,
		SmsResult,
		SmsBillingFee,
		operator,
		ReceiveContacts,
		FDataStatu,
		relatieid
	)
	SELECT
		IFNULL((SELECT MAX(TaskID) FROM ld_smssend),0)+1,
		CONCAT('sms',DATE_FORMAT(NOW(),'%Y%m%d'),LPAD(@cnt+1,8,0)),
		tmp_mobile,
		tmp_content,
		tmp_sendtime,
		NOW(),
		0,
		0.00,
		tmp_sender,
		tmp_jieshouren,
		0,
		tmp_relatedid;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_defaultcreateprofileon` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_defaultcreateprofileon`(
    modulename varchar(50),
    permissions int(19)
)
begin
	declare done int default 0;
	declare pprofileid  int ;
	declare cur1 CURSOR FOR SELECT profileid FROM ld_profile where profileid!=1;
declare continue handler  for not   found  SET done =1;
	set @sql = concat('select tabid into @tabid from ld_tab where name=','''',modulename,'''');
prepare stmt from @sql;
execute stmt;
deallocate  prepare stmt;
OPEN cur1;
Fetch cur1 into pprofileid;
loop1: while  done<>1 DO
	set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',4,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=4)' );
prepare stmt from @sql;
execute stmt;
deallocate prepare stmt;
set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',11,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=11)' );
prepare stmt from @sql;
execute stmt;
deallocate prepare stmt;
Fetch cur1 into pprofileid;
end while loop1;
close cur1;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_read_tmpreminder` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_read_tmpreminder`(
)
BEGIN
	DECLARE tmp_id INT(19) DEFAULT 0;
	DECLARE tmp_content text DEFAULT '';
	DECLARE tmp_recieverid INT(19) DEFAULT 0;
	DECLARE tmp_remindtime datetime;
	DECLARE tmp_reltab varchar(100) DEFAULT '';
	DECLARE tmp_related_to INT(19) DEFAULT 0;
	DECLARE tmp_ruleid INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR 
		SELECT
			id,
			content,
			reminderid,
			remindtime,
			reltab,
			related_to,
			reminds_ruleid 
		FROM ld_tmpreminder 
		WHERE remindtime<=NOW() 
			AND IFNULL(content,'') not like '%[var.%'
		ORDER BY remindtime DESC LIMIT 50;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	OPEN Mycur;
	FETCH Mycur INTO tmp_id,tmp_content,tmp_recieverid,tmp_remindtime,tmp_reltab,tmp_related_to,tmp_ruleid;
	WHILE (tmp_id IS NOT NULL) DO
		DELETE FROM ld_tmpreminder WHERE id=tmp_id;
		set @maxid=0;
		select max(crmid) into @maxid from ld_crmentity;
		insert into ld_crmentity(crmid,setype)
		select @maxid+1,'Reminds';
		
		update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			
		insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
		select @maxid+1,tmp_content,tmp_remindtime,tmp_recieverid,'未读',tmp_related_to,tmp_reltab,0,0,tmp_ruleid,0,0,0,tmp_remindtime,tmp_remindtime,null,0
		from dual where not exists (select 1 from ld_reminds where content=tmp_content AND recieverid=tmp_recieverid and related_to=tmp_related_to and date_time=tmp_remindtime and reminds_ruleid=tmp_ruleid);

	FETCH Mycur INTO tmp_id,tmp_content,tmp_recieverid,tmp_remindtime,tmp_reltab,tmp_related_to,tmp_ruleid;
	END WHILE;
	CLOSE Mycur;	
	
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_refresh_advance_stage` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_refresh_advance_stage`()
BEGIN

	DECLARE tmp_tablename varchar(50) DEFAULT '';
	DECLARE tmp_fieldname varchar(100) DEFAULT '';
	DECLARE tmp_dir_tablename varchar(50) DEFAULT '';
	DECLARE tmp_entityidfield varchar(150) DEFAULT '';

	DECLARE MYCUSOR CURSOR FOR
        SELECT
            (SELECT tablename FROM ld_field a WHERE tabid=ld_settings_advance.tabid AND columnname='createdtime') AS `tablename`,
            ld_field.`columnname` ,
            ld_field.`tablename` as `dir_tablename`,
            ld_entityname.entityidfield
        FROM ld_settings_advance
        LEFT JOIN ld_field ON ld_field.tabid = ld_settings_advance.tabid AND ld_field.fieldname = ld_settings_advance.module_field
        LEFT JOIN ld_entityname on ld_entityname.tabid = ld_settings_advance.tabid
        WHERE (`enable` = 'yes' or `showadvancemobile` = 'yes');
    DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_tablename = NULL,tmp_fieldname = NULL;

	set @disable_triggers = 'ldcrm_refresh_advance_stage';

    OPEN MYCUSOR;
    FETCH MYCUSOR INTO tmp_dir_tablename,tmp_fieldname,tmp_tablename,tmp_entityidfield;
    WHILE(tmp_tablename IS NOT NULL) DO
    
        SET @update_sql = (
                    CASE
                        WHEN tmp_tablename = tmp_dir_tablename THEN CONCAT("UPDATE ",tmp_dir_tablename," SET advance_stage = ",tmp_fieldname," WHERE deleted=0 AND advance_stage <> ",tmp_fieldname,";")
                        ELSE CONCAT("UPDATE ",tmp_dir_tablename," LEFT JOIN ",tmp_tablename," ON ",tmp_tablename,".",tmp_entityidfield," = ",tmp_dir_tablename,".",tmp_entityidfield," SET advance_stage = ",tmp_fieldname," WHERE deleted=0 AND advance_stage <> ",tmp_fieldname,";")
                    END
                );
        SET @update_sql=REPLACE(@update_sql,'ld_faqscf.id', 'ld_faqscf.faqid');
        
        PREPARE stmtt FROM @update_sql;
        EXECUTE stmtt;
        DEALLOCATE PREPARE stmtt;

        FETCH MYCUSOR INTO tmp_dir_tablename,tmp_fieldname,tmp_tablename,tmp_entityidfield;
    END WHILE;
    CLOSE MYCUSOR;

    set @disable_triggers = NULL;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_remindsdata_delete` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_remindsdata_delete`(
)
BEGIN

	DECLARE tmp_deldataids MEDIUMTEXT DEFAULT NULL;

	
	DECLARE REMIND_DELCUSOR CURSOR FOR 
		SELECT
			GROUP_CONCAT(remindsid) AS ids
		FROM (
			SELECT 
				remindsid
			FROM ld_reminds_accepted 
			WHERE date_time<DATE_SUB(CURDATE(),INTERVAL 3 MONTH)
			LIMIT 200
		) a;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_deldataids = NULL;

	OPEN REMIND_DELCUSOR; 
	FETCH REMIND_DELCUSOR INTO tmp_deldataids;
	WHILE(tmp_deldataids IS NOT NULL) DO
		DELETE FROM ld_reminds_accepted WHERE FIND_IN_SET(remindsid,tmp_deldataids);
		DELETE FROM ld_crmentity WHERE setype='Reminds' AND FIND_IN_SET(crmid,tmp_deldataids);
		FETCH REMIND_DELCUSOR INTO tmp_deldataids;
	END WHILE;
	CLOSE REMIND_DELCUSOR;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_remindsdata_transfer` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_remindsdata_transfer`(
)
BEGIN

	DECLARE tmp_dataids MEDIUMTEXT DEFAULT NULL;

	
	DECLARE REMIND_CUSOR CURSOR FOR 
		SELECT
			GROUP_CONCAT(remindsid) AS ids
		FROM (
			SELECT 
				remindsid
			FROM ld_reminds 
			WHERE date_time<DATE_SUB(CURDATE(),INTERVAL 1 MONTH)
				AND (
					status_rmd='已读' 
					OR push_to_yzj=3
					OR push_to_weixin=3 
					OR push_to_ding=3
			)
			LIMIT 1000
		) a;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_dataids = NULL;

	OPEN REMIND_CUSOR; 
	FETCH REMIND_CUSOR INTO tmp_dataids;
	WHILE(tmp_dataids IS NOT NULL) DO
		INSERT INTO ld_reminds_accepted
		SELECT * FROM ld_reminds WHERE FIND_IN_SET(remindsid,tmp_dataids);

		DELETE FROM ld_reminds WHERE FIND_IN_SET(remindsid,tmp_dataids);

		FETCH REMIND_CUSOR INTO tmp_dataids;
	END WHILE;
	CLOSE REMIND_CUSOR;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
