/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_update_sykq_all` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_update_sykq_all`(
)
BEGIN
	
	SET @disable_triggers='abcdefg';
	UPDATE ld_minusjobbill a
	LEFT JOIN ld_minusjobbillscf b ON b.minusjobbillid=a.minusjobbillid
	LEFT JOIN (
		SELECT
			a.id,
			IFNULL(b.add_hours,0)-IFNULL(c.min_hours,0) AS total_sy_tx,
			CASE
				WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN 0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN 0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN 40
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN 80
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN 15*8
				ELSE 120
			END AS total_nj_all,
			(SELECT
				SUM(y.costtime)
			FROM ld_minusjobbill x
			LEFT JOIN ld_minusjobbilldetail y ON y.id=x.minusjobbillid
			WHERE x.deleted=0
				AND x.approvestatus='已批准'
				AND y.minusjobtype='年假'
				AND IFNULL(y.description,'') NOT LIKE '%兑换%'
				AND x.smownerid=a.id
				AND y.starttime>a.this_njstart) AS totqal_nj_use,
			a.this_njstart
		FROM (
			SELECT
				a.id,
				a.last_name,
				a.`status`,
				a.hire_date,
				CASE
					WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
					WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
						DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
					ELSE
						DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
				END AS this_njstart,
				CASE
					WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
					ELSE
						DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
				END AS extra_njend
			FROM ld_users a
		) a
		LEFT JOIN (
			SELECT
				a.smownerid,
				SUM(b.costtime) AS add_hours
			FROM ld_addjobbill a
			LEFT JOIN ld_addjobbilldetail b ON b.id=a.addjobbillid
			WHERE a.deleted=0
				AND a.approvestatus='已批准'
			GROUP BY a.smownerid
		) b ON b.smownerid=a.id
		LEFT JOIN (
			SELECT
				a.smownerid,
				SUM(b.costtime) AS min_hours
			FROM ld_minusjobbill a
			LEFT JOIN ld_minusjobbilldetail b ON b.id=a.minusjobbillid
			WHERE a.deleted=0
				AND a.approvestatus='已批准'
				AND b.minusjobtype='调休'
			GROUP BY a.smownerid
		) c ON c.smownerid=a.id
	) c ON c.id=a.smownerid
	SET 
		b.sytx=c.total_sy_tx,
		b.synj=CONCAT(IFNULL(c.total_nj_all,0)-IFNULL(c.totqal_nj_use,0),IFNULL(CONCAT('(',c.this_njstart,')'),''));

	UPDATE ld_addjobbill a
	LEFT JOIN ld_addjobbillscf b ON b.addjobbillid=a.addjobbillid
	LEFT JOIN (
		SELECT
			a.id,
			IFNULL(b.add_hours,0)-IFNULL(c.min_hours,0) AS total_sy_tx,
			CASE
				WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN 0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN 0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN 40
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN 80
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN 15*8
				ELSE 120
			END AS total_nj_all,
			(SELECT
				SUM(y.costtime)
			FROM ld_minusjobbill x
			LEFT JOIN ld_minusjobbilldetail y ON y.id=x.minusjobbillid
			WHERE x.deleted=0
				AND x.approvestatus='已批准'
				AND y.minusjobtype='年假'
				AND IFNULL(y.description,'') NOT LIKE '%兑换%'
				AND x.smownerid=a.id
				AND y.starttime>a.this_njstart) AS totqal_nj_use,
			a.this_njstart
		FROM (
			SELECT
				a.id,
				a.last_name,
				a.`status`,
				a.hire_date,
				CASE
					WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
					WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
						DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
					ELSE
						DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
				END AS this_njstart,
				CASE
					WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
					ELSE
						DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
				END AS extra_njend
			FROM ld_users a
		) a
		LEFT JOIN (
			SELECT
				a.smownerid,
				SUM(b.costtime) AS add_hours
			FROM ld_addjobbill a
			LEFT JOIN ld_addjobbilldetail b ON b.id=a.addjobbillid
			WHERE a.deleted=0
				AND a.approvestatus='已批准'
			GROUP BY a.smownerid
		) b ON b.smownerid=a.id
		LEFT JOIN (
			SELECT
				a.smownerid,
				SUM(b.costtime) AS min_hours
			FROM ld_minusjobbill a
			LEFT JOIN ld_minusjobbilldetail b ON b.id=a.minusjobbillid
			WHERE a.deleted=0
				AND a.approvestatus='已批准'
				AND b.minusjobtype='调休'
			GROUP BY a.smownerid
		) c ON c.smownerid=a.id
	) c ON c.id=a.smownerid
	SET 
		b.sytx=c.total_sy_tx,
		b.synj=concat(IFNULL(c.total_nj_all,0)-IFNULL(c.totqal_nj_use,0),IFNULL(CONCAT('(',c.this_njstart,')'),''));
	SET @disable_triggers=NULL;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_update_sykq_byuserid` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_update_sykq_byuserid`(
	tmp_id int(19)
)
BEGIN

	SET @disable_triggers='abcdefg';
	UPDATE ld_minusjobbill a
	LEFT JOIN ld_minusjobbillscf b ON b.minusjobbillid=a.minusjobbillid
	LEFT JOIN (
		SELECT
			a.id,
			IFNULL(b.add_hours,0)-IFNULL(c.min_hours,0) AS total_sy_tx,
			CASE
				WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN 0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN 0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN 40
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN 80
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN 15*8
				ELSE 120
			END AS total_nj_all,
			(SELECT
				SUM(y.costtime)
			FROM ld_minusjobbill x
			LEFT JOIN ld_minusjobbilldetail y ON y.id=x.minusjobbillid
			WHERE x.deleted=0
				AND x.approvestatus='已批准'
				AND y.minusjobtype='年假'
				AND IFNULL(y.description,'') NOT LIKE '%兑换%'
				AND x.smownerid=a.id
				AND y.starttime>a.this_njstart) AS totqal_nj_use,
			a.this_njstart
		FROM (
			SELECT
				a.id,
				a.last_name,
				a.`status`,
				a.hire_date,
				CASE
					WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
					WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
						DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
					ELSE
						DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
				END AS this_njstart,
				CASE
					WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
					ELSE
						DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
				END AS extra_njend
			FROM ld_users a
			WHERE a.id=tmp_id
		) a
		LEFT JOIN (
			SELECT
				a.smownerid,
				SUM(b.costtime) AS add_hours
			FROM ld_addjobbill a
			LEFT JOIN ld_addjobbilldetail b ON b.id=a.addjobbillid
			WHERE a.deleted=0
				AND a.approvestatus='已批准'
				AND a.smownerid=tmp_id
			GROUP BY a.smownerid
		) b ON b.smownerid=a.id
		LEFT JOIN (
			SELECT
				a.smownerid,
				SUM(b.costtime) AS min_hours
			FROM ld_minusjobbill a
			LEFT JOIN ld_minusjobbilldetail b ON b.id=a.minusjobbillid
			WHERE a.deleted=0
				AND a.approvestatus='已批准'
				AND b.minusjobtype='调休'
				AND a.smownerid=tmp_id
			GROUP BY a.smownerid
		) c ON c.smownerid=a.id
	) c ON c.id=a.smownerid
	SET 
		b.sytx=c.total_sy_tx,
		b.synj=CONCAT(IFNULL(c.total_nj_all,0)-IFNULL(c.totqal_nj_use,0),IFNULL(CONCAT('(',c.this_njstart,')'),''))
	WHERE a.smownerid=tmp_id;


	UPDATE ld_addjobbill a
	LEFT JOIN ld_addjobbillscf b ON b.addjobbillid=a.addjobbillid
	LEFT JOIN (
		SELECT
			a.id,
			IFNULL(b.add_hours,0)-IFNULL(c.min_hours,0) AS total_sy_tx,
			CASE
				WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN 0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN 0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN 40
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN 80
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN 15*8
				ELSE 120
			END AS total_nj_all,
			(SELECT
				SUM(y.costtime)
			FROM ld_minusjobbill x
			LEFT JOIN ld_minusjobbilldetail y ON y.id=x.minusjobbillid
			WHERE x.deleted=0
				AND x.approvestatus='已批准'
				AND y.minusjobtype='年假'
				AND IFNULL(y.description,'') NOT LIKE '%兑换%'
				AND x.smownerid=a.id
				AND y.starttime>a.this_njstart) AS totqal_nj_use,
			a.this_njstart
		FROM (
			SELECT
				a.id,
				a.last_name,
				a.`status`,
				a.hire_date,
				CASE
					WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
					WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
						DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
					ELSE
						DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
				END AS this_njstart,
				CASE
					WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
					ELSE
						DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
				END AS extra_njend
			FROM ld_users a
			WHERE a.id=tmp_id
		) a
		LEFT JOIN (
			SELECT
				a.smownerid,
				SUM(b.costtime) AS add_hours
			FROM ld_addjobbill a
			LEFT JOIN ld_addjobbilldetail b ON b.id=a.addjobbillid
			WHERE a.deleted=0
				AND a.approvestatus='已批准'
				AND a.smownerid=tmp_id
			GROUP BY a.smownerid
		) b ON b.smownerid=a.id
		LEFT JOIN (
			SELECT
				a.smownerid,
				SUM(b.costtime) AS min_hours
			FROM ld_minusjobbill a
			LEFT JOIN ld_minusjobbilldetail b ON b.id=a.minusjobbillid
			WHERE a.deleted=0
				AND a.approvestatus='已批准'
				AND b.minusjobtype='调休'
				AND a.smownerid=tmp_id
			GROUP BY a.smownerid
		) c ON c.smownerid=a.id
	) c ON c.id=a.smownerid
	SET 
		b.sytx=c.total_sy_tx,
		b.synj=concat(IFNULL(c.total_nj_all,0)-IFNULL(c.totqal_nj_use,0),IFNULL(CONCAT('(',c.this_njstart,')'),''))
	WHERE a.smownerid=tmp_id;
	SET @disable_triggers=NULL;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ld_addtable_homeboard_plate_filter` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ld_addtable_homeboard_plate_filter`(

)
BEGIN

IF NOT EXISTS (select 1 from information_schema.`COLUMNS` where TABLE_SCHEMA=database() and TABLE_NAME='ld_homeboard_plate_filter') THEN

	CREATE TABLE if not EXISTS `ld_homeboard_plate_filter` (
		`filterid` int(11) NOT NULL AUTO_INCREMENT,
		`boardstuffid` int(11) NOT NULL COMMENT"ld_homeboard_plate_stuff表的主键id ",
		`conditionkey` varchar(255) DEFAULT NULL COMMENT"条件关键词 ",
		`isrelated` varchar(20) DEFAULT 'no' COMMENT"是否关联该条件",
		`filters` varchar(255) DEFAULT NULL COMMENT"筛选条件 自定义统计图下拉选字段（用户字段、时间字段、审批字段）、sql统计图下拉选变量（用户组件、时间组件、审批组件）",
		`filtermodule` varchar(100) DEFAULT NULL,
		`stuffmodule` varchar(100) DEFAULT NULL COMMENT"组件哪个模块的筛选（仅想签约排行榜这种涉及两个模块的组件会用到该字段）",
		`advance_demand` text DEFAULT NULL COMMENT"高级查找条件",
		`advance_demand_groups` text DEFAULT NULL COMMENT"高级查找条件分组",
		PRIMARY KEY (`filterid`)
	) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8;


	INSERT INTO ld_homeboard_plate_filter(boardstuffid,conditionkey,isrelated,filters,filtermodule,stuffmodule,advance_demand,advance_demand_groups)
	SELECT
		s.boardstuffid,
		(case when f.uses='smownerid' then 'usercomponent' when f.uses='start' then 'timecomponent1' when f.uses='end' then 'timecomponent2' when f.uses='approvestatus' then 'approvestatuscomponent' else '' end) as conditionkey,
		'yes' as isrelated,
		f.id as filters,
		'' as filtermodule ,
		'' as stuffmodule,
		'' as advance_demand,
		'' as advance_demand_groups
	from ld_homeboard_plate_stuff s
	inner join ld_customreport c on c.report_id=s.stuffid and s.stufftype="customreport"
	inner  join ld_customreportsql_filter f on f.report_id=c.report_id
	where f.uses in ('smownerid','start','end','approvestatus');


	INSERT INTO ld_homeboard_plate_filter(boardstuffid,conditionkey,isrelated,filters,filtermodule,stuffmodule,advance_demand,advance_demand_groups)
	SELECT
		s.boardstuffid,
		(case when f.comparator='show_athome_person' then 'usercomponent' when f.comparator='show_athome_timecheck' then 'timecomponent' when f.comparator='show_athome_approve' then 'approvestatuscomponent' else '' end) as conditionkey,
		'yes' as isrelated,
		(case when ifnull(f.columns,'')!='' then REPLACE(`columns`,REVERSE(SUBSTRING(REVERSE(`columns`),LOCATE(':',REVERSE(`columns`))+1,LOCATE('_',REVERSE(`columns`))-LOCATE(':',REVERSE(`columns`))-1)),'fieldlabel')
			  when ifnull(f.columns,'')='' and f.comparator='show_athome_person' then CONCAT(t.main_tablename,':smownerid:assigned_user_id:',c.mainmodule,'_fieldlabel:V')
			  when ifnull(f.columns,'')='' and f.comparator='show_athome_approve' then CONCAT(t.main_tablename,':approvestatus:approvestatus:',c.mainmodule,'_fieldlabel:V') end  ) as filters,
		c.mainmodule as filtermodule ,
		c.mainmodule as stuffmodule,
		'' as advance_demand,
		'' as advance_demand_groups
	from ld_homeboard_plate_stuff s
	inner join ld_customreport c on c.report_id=s.stuffid and s.stufftype="customreport"
	inner join ld_customreport_cvadvfilter f on f.report_id=c.report_id
	left join ld_tab t on t.name=c.mainmodule
	where f.comparator IN ('show_athome_timecheck','show_athome_person','show_athome_approve');

	call AddColumn('ld_stuff','datarangmodule','varchar','200','');

	update ld_stuff set datarangmodule=relatedmodule;
	update ld_stuff set datarangmodule='SalesOrder,ServiceContracts' where stufftitle='SALESSIXMONTH';

	update ld_stuff set datarangmodule='SalesOrder,ServiceContracts,CashBill' where stufftitle='ANNUALSALES';
	update ld_stuff set datarangmodule='Products' where stufftitle='INVENTORYDATA';
	update ld_stuff set datarangmodule='SalesOrder,ServiceContracts' where stufftitle='AMOUNTMONTHCONTRACTYEAR';
	update ld_stuff set datarangmodule='CashBill' where stufftitle='BACKAMOUNTMONTHYEAR';
	update ld_stuff set datarangmodule='SalesOrder,ServiceContracts,PaymentPlan,Invoice,PurchaseOrder,SendCashBill,SendPayment' where stufftitle='RECEIVESUMMARY';
	update ld_stuff set datarangmodule='Accounts,Calendar,Potentials,SalesOrder,ServiceContracts,CashBill' where stufftitle='SUBORDINATEMOTHSALESDATA';

	update ld_stuff set datarangmodule='Accounts,Calendar,Potentials,SalesOrder,ServiceContracts,CashBill' where stufftitle='Penson Month Sales';
	update ld_stuff set datarangmodule='SalesOrder,ServiceContracts' where stufftitle='INDIVIDUALSIXMONTH';
	update ld_stuff set datarangmodule='Calendar' where stufftitle='OVERSERVENDAYSSCHEDULE';
	update ld_stuff set datarangmodule='Calendar' where stufftitle='FUTURESEVENDAYSSCHEDULE';
	update ld_stuff set datarangmodule='Calendar' where stufftitle='EXPIREDAGENDA';
	update ld_stuff set datarangmodule='Accounts' where stufftitle='TODAYCONTACTCUSTOMER';
	update ld_stuff set datarangmodule='Potentials' where stufftitle='LATESTPOTENTIALS';
	update ld_stuff set datarangmodule='Quotes' where stufftitle='LATESTQUOTATION';
	update ld_stuff set datarangmodule='SalesOrder' where stufftitle='NEWCONTRACTORDERS';
	update ld_stuff set datarangmodule='Invoice' where stufftitle='LATESTINVOICE';
	update ld_stuff set datarangmodule='Potentials' where stufftitle='SALESFUNNEL';
	update ld_stuff set datarangmodule='PaymentPlan' where stufftitle='WITHINPAYMENTPLAN';
	update ld_stuff set datarangmodule='Expense' where stufftitle='LATESTEXPENSE';
	update ld_stuff set datarangmodule='CashBill' where stufftitle='LATESTCASHBILL';
	update ld_stuff set datarangmodule='SendCashBill' where stufftitle='LATESTSENDCASHBILL';
	update ld_stuff set datarangmodule='CashDeposit' where stufftitle='LATESTCASHDEPOSIT';
	update ld_stuff set datarangmodule='PutCash' where stufftitle='LATESTPUTCASH';

	update ld_stuff set datarangmodule='PutCash,CashDeposit,SendCashBill,CashBill,Commission,Expense' where stufftitle='BANKCASH';
	update ld_stuff set datarangmodule='PublicAnnouncement' where stufftitle='PUBLICANNOUNCEMENT';
	update ld_stuff set datarangmodule='SalesOrder,ServiceContracts,CashBill' where stufftitle='SALESCHARTS';

	update ld_stuff set datarangmodule='SalesOrder,ServiceContracts,CashBill,CashBack' where stufftitle='transaction';
	update ld_stuff set datarangmodule='SalesOrder,ServiceContracts,CashBill,Accounts,Invoice,OutboundOrder' where stufftitle='COMPLATIONRATESIXMONTH';
	update ld_stuff set datarangmodule='Invoice' where stufftitle='INVOICEAMOUNTYEAR';
	update ld_stuff set datarangmodule='OutboundOrder' where stufftitle='OUTBOUNDORDERAMOUNTYEAR';
	update ld_stuff set datarangmodule='Calendar' where stufftitle='日程管理';

	update ld_stuff set datarangmodule='Potentials' where stufftitle='StatisticsPotentialsBySalesPersonAndSalesStage';
	update ld_stuff set datarangmodule='Potentials' where stufftitle='StatisticalPotentialsByTheAccountIndustryAndSalesStage';
	update ld_stuff set datarangmodule='ContactRecords,Singin' where stufftitle='ContactTimesRanking';
	update ld_stuff set datarangmodule='SalesOrder,Products' where stufftitle='ProductsSalesRanking';
	update ld_stuff set datarangmodule='HelpDesk' where stufftitle='ServiceKanban';

	insert into ld_homeboard_plate_filter (boardstuffid,conditionkey,isrelated,filters,filtermodule,stuffmodule,advance_demand,advance_demand_groups)
	SELECT
		s.boardstuffid,'highsearch','yes','','ServiceContracts','ServiceContracts','[null,{"groupid":"1","columnname":"ld_servicecontracts:invoicestatus:contract_status:ServiceContracts_合同状态:V","comparator":"n","value":"已作废","columncondition":""}]','[null,{"groupcondition":""}]'
	from ld_homeboard_plate_stuff s left join ld_stuff on ld_stuff.stuffid=s.stuffid
	where ld_stuff.datarangmodule like '%ServiceContracts%';

	insert into ld_homeboard_plate_filter (boardstuffid,conditionkey,isrelated,filters,filtermodule,stuffmodule,advance_demand,advance_demand_groups)
	SELECT
		s.boardstuffid,'highsearch','yes','','SalesOrder','SalesOrder','[null,{"groupid":"1","columnname":"ld_salesorder:sostatus:sostatus:SalesOrder_订单状态:V","comparator":"n","value":"已作废","columncondition":""}]','[null,{"groupcondition":""}]'
	from ld_homeboard_plate_stuff s left join ld_stuff on ld_stuff.stuffid=s.stuffid
	where ld_stuff.datarangmodule like '%SalesOrder%';

	insert into ld_homeboard_plate_filter (boardstuffid,conditionkey,isrelated,filters,filtermodule,stuffmodule,advance_demand,advance_demand_groups)
	SELECT
		s.boardstuffid,'highsearch','yes','','Invoice','Invoice','[null,{"groupid":"1","columnname":"ld_invoice:invoicestatus:invoicestatus:Invoice_状态:V","comparator":"n","value":"已作废","columncondition":""}]','[null,{"groupcondition":""}]'
	from ld_homeboard_plate_stuff s left join ld_stuff on ld_stuff.stuffid=s.stuffid
	where ld_stuff.datarangmodule like '%Invoice%';
	
END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ld_homeboard_updatesequence_history` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ld_homeboard_updatesequence_history`()
BEGIN
	IF NOT EXISTS (select 1 from information_schema.`COLUMNS` where TABLE_SCHEMA=database() and TABLE_NAME='ld_homeboard' and column_name='sequence') THEN
		call AddColumn('ld_homeboard','sequence','tinyint','4',NULL);
		SET @seq_home = 0;
		UPDATE ld_homeboard SET sequence = (@seq_home:=@seq_home+1) WHERE boardtype = 'Home' ORDER BY modifiedtime;
		SET @seq_visual = 0;
		update ld_homeboard set sequence = (@seq_visual :=@seq_visual + 1) WHERE boardtype = 'VisualAnalysis' ORDER BY modifiedtime;
	END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `leads_singlerecycle_highsea_program` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `leads_singlerecycle_highsea_program`(IN tmp_from_pool_id INT(11))
BEGIN
	declare done  int  default 0;
	DECLARE target_pool_id varchar(200);
	DECLARE tmp_grammeid varchar(200);
	declare cur1 CURSOR FOR SELECT programmeid,pool_id from ld_module_recovery_programme where modulename = 'Leads' and active = 'yes' and from_pool_id = tmp_from_pool_id ORDER BY sequence;
	declare continue handler  for not   found  SET done =1;
	OPEN cur1;
		Fetch cur1 into tmp_grammeid,target_pool_id;
			loop1: while  done<>1 DO
				call leads_singlerecycle_highsea_rule(tmp_from_pool_id,target_pool_id,tmp_grammeid);
				call leads_singlerecycle_highsea_rule_beforeremind(tmp_from_pool_id,tmp_grammeid);
		Fetch cur1 into tmp_grammeid,target_pool_id;
	end while loop1;
	close cur1;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `leads_singlerecycle_highsea_rule` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `leads_singlerecycle_highsea_rule`(IN tmp_pool_id INT(11),IN target_pool_id INT(11),IN tmp_grammeid INT(11))
label_a:BEGIN

	DECLARE var_tabname varchar(100);
	DECLARE var_columnname varchar(100);
	DECLARE var_tablename varchar(100);
	DECLARE var_condition varchar(50);
	DECLARE var_smownercolumn varchar(50);
	declare var_leadsidcolumnname varchar(100);
	DECLARE var_days int(11);
	DECLARE var_otherwhere varchar(200);
	declare var_iscycle varchar(100);
	declare done  int  default 0;

	declare cur1 CURSOR FOR select tabname,ld_leads_set_rule.columnname,ld_field.tablename ,ld_leads_set_rule.iscycle, `condition`,ld_leads_set_rule.days
                                 ,ld_leads_set_rule.otherwhere from ld_leads_set_rule  inner join ld_tab on ld_tab.name=ld_leads_set_rule.tabname and (presence in(0,2) or ld_leads_set_rule.tabname='singin')
                                                                                       INNER JOIN ld_field on ld_field.tabid=ld_tab.tabid and ld_leads_set_rule.columnname=ld_field.columnname
    and (ld_field.presence in(0,2) ) where ld_leads_set_rule.type='complete' and ld_leads_set_rule.`status`='active' and programmeid = tmp_grammeid;
	declare continue handler  for not   found  SET done =1;
	set @tmpint=0;
	set @tmpsql='';
	
	select max(ld_leads_set_rule.days) into @maxdays
	from ld_leads_set_rule  inner join ld_tab on ld_tab.name=ld_leads_set_rule.tabname and (presence in(0,2) or ld_leads_set_rule.tabname='singin')
													INNER JOIN ld_field on ld_field.tabid=ld_tab.tabid and ld_leads_set_rule.columnname=ld_field.columnname and ld_field.presence in(0,2)
	where ld_leads_set_rule.type='complete' and ld_leads_set_rule.`status`='active' and programmeid = tmp_grammeid;

	select IF(ld_users.id>0,transfer_users,0) into @allotaccount from 
		ld_module_recovery_programme LEFT join ld_users on ld_users.id=transfer_users
		where modulename = 'Leads' and ld_module_recovery_programme.programmeid = tmp_grammeid;
	
	if  ifnull(@allotaccount,0)=0  then
				set @allotaccount=0;
	end if;
	select recycleselect into @recycleselect from ld_module_recovery_programme where programmeid = tmp_grammeid;

	if @recycleselect is not null and @recycleselect<>'' then
				set @recycleselect=concat( '( ', @recycleselect,' ) as recyclewheretableset ');
	end if;
	
OPEN cur1;

Fetch cur1 into var_tabname,var_columnname,var_tablename,var_iscycle,var_condition,var_days,var_otherwhere;
loop1: while  done<>1 DO
			if var_tablename='ld_singin' THEN
					set var_smownercolumn='userid';
					set var_leadsidcolumnname='record';
else
				set	var_smownercolumn='smownerid' ;
				set var_leadsidcolumnname='leads_id';
end if;
		  if(var_condition='and' ) then

					set @tmpsqlone =concat("select ld_leads.leadsid,ld_leads.allocatedate from ld_leads ");
					set @tmpsqlone=concat(@tmpsqlone," inner join ",var_tablename,' on ',var_tablename,'.',var_leadsidcolumnname,'=ld_leads.leadsid ');
					set @tmpsqlone=concat(@tmpsqlone," and  ",var_tablename,'.',var_smownercolumn,'=ld_leads.smownerid' );

					set @tmpsqlone=concat(@tmpsqlone ,"  where  ",var_tablename,".deleted=0");
					 if var_otherwhere is not null and  var_otherwhere<>'' then
							set @tmpsqlone=concat(@tmpsqlone,var_otherwhere);
end if;

					if var_iscycle='yes' then
							set @tmpsqlone=concat( @tmpsqlone,' group by ld_leads.leadsid ') ;
							set @tmpsqlone=concat(@tmpsqlone,"   having datediff(curdate(), case when ld_leads.allocatedate> max( " ,var_tablename,'.',var_columnname," )  then ld_leads.allocatedate else max( " ,var_tablename,'.',var_columnname," ) end  ) >",var_days);
else
							set @tmpsqlone=concat(@tmpsqlone," and ld_leads.allocatedate<=",var_tablename,'.',var_columnname);
							set @tmpsqlone=concat( @tmpsqlone,' group by ld_leads.leadsid ') ;
							set @tmpsqlone=concat(@tmpsqlone,"  having  datediff(min( ",var_tablename,'.',var_columnname,"),ld_leads.allocatedate)>",var_days);
end if;
					set @tmpsqltwo=concat('select ld_leads.leadsid,ld_leads.allocatedate from  ld_leads LEFT JOIN(select ld_leads.leadsid
							from ld_leads inner join ',var_tablename,' on ld_leads.leadsid=',var_tablename,'.',var_leadsidcolumnname,'
								and ld_leads.smownerid=',var_tablename,'.',var_smownercolumn,'  where ',var_tablename,'.deleted=0' );

					 if var_otherwhere is not null and  var_otherwhere<>'' then
							set @tmpsqltwo=concat(@tmpsqltwo, var_otherwhere);
end if;
					set @tmpsqltwo=concat(@tmpsqltwo,' ) 	as ttt_',var_tablename,'  on ld_leads.leadsid=ttt_',var_tablename,'.leadsid   where ttt_',var_tablename,'.leadsid is null  ' );
					set @tmpsqltwo=concat(@tmpsqltwo," having datediff(curdate(),ld_leads.allocatedate ) >",var_days);

					set @tmpthree=concat( @tmpsqlone,' union all ',@tmpsqltwo);
					set @tmpsql=concat(@tmpsql," select * from ( ",@tmpthree," ) as  tttt_",var_tabname);
					set @tmpsql=concat(@tmpsql,' union all ' );

			elseif (var_condition='or')  then
				set @tmpsql=concat(@tmpsql ,' select ld_leads.leadsid,ld_leads.allocatedate from ld_leads inner join '  ,var_tablename,' on ',var_tablename,'.',var_leadsidcolumnname,'=ld_leads.leadsid  ');

				set @tmpsql=concat(@tmpsql,' and ' ,var_tablename,'.',var_smownercolumn,'=ld_leads.smownerid ' );

				set @tmpsql=concat(@tmpsql,' where  ' , var_tablename,'.deleted=0 ' );
			  if var_otherwhere is not null and  var_otherwhere<>'' then
					set @tmpsql=concat(@tmpsql,var_otherwhere);
end if;

			  if var_iscycle='yes' then
						set @tmpsql=concat( @tmpsql,' group by ld_leads.leadsid ') ;
						set @tmpsql=concat(@tmpsql," having    datediff ( curdate(), case when ld_leads.allocatedate> max( ",var_tablename,'.',var_columnname," ) then ld_leads.allocatedate else max( ",var_tablename,'.',var_columnname," )  end )<=",var_days );

ELSE
				  set @tmpsql=concat(@tmpsql," and ld_leads.allocatedate<=",var_tablename,'.',var_columnname);
					set @tmpsql=concat( @tmpsql,' group by ld_leads.leadsid ') ;
					set @tmpsql=concat(@tmpsql,"  having datediff(min( ",var_tablename,'.',var_columnname,"),ld_leads.allocatedate)<=",var_days);
end if;
				set @tmpsql=concat(@tmpsql,' union all ' );

end if;
			set @tmpint=@tmpint+1;
Fetch cur1 into var_tabname,var_columnname,var_tablename,var_iscycle,var_condition,var_days,var_otherwhere;
end while loop1;
close cur1;

if @tmpint>0 then
		set @len=CHAR_LENGTH(' union all ');
		set @tmpsql=left(@tmpsql,CHAR_LENGTH(@tmpsql)-@len);

	  if var_condition='or'  then

			set @sql=concat(' select leadsid from (',@tmpsql, ') as tmpone group by leadsid ') ;
			set @TMPSQL_ONE=concat( ' select "系统","LOGPUBLICALLOCATELEADS",now(), ld_leads.leadsid,ld_leads.pool_id  from ld_leads left join ( ',@sql,' ) as lingdangtmp  on  lingdangtmp.leadsid=ld_leads.leadsid ') ;
			set @TMPSQL_LOG_ONE=concat( ' select "系统","LOGPUBLICALLOCATELEADS",now(), ld_leads.leadsid,ld_leads.pool_id,ld_leads.smownerid,"',tmp_grammeid,'" as log_grammeid  from ld_leads left join ( ',@sql,' ) as lingdangtmp  on  lingdangtmp.leadsid=ld_leads.leadsid ') ;
			if @recycleselect<>'' and @recycleselect is not null THEN
				set @TMPSQL_ONE=concat(@TMPSQL_ONE,' left join ',@recycleselect,' on recyclewheretableset.leadsid=ld_leads.leadsid ');
				set @TMPSQL_LOG_ONE=concat(@TMPSQL_LOG_ONE,' left join ',@recycleselect,' on recyclewheretableset.leadsid=ld_leads.leadsid ');
			end if;
		  set @TMPSQL_TWO=concat(' where ld_leads.deleted=0 and( ld_leads.publicaccount=2 or ld_leads.publicaccount=3) and ld_leads.pool_id =  ',tmp_pool_id);

			set @TMPSQL_TWO=concat(@TMPSQL_TWO,' and lingdangtmp.leadsid is null  and datediff(curdate(),ld_leads.allocatedate)>',@maxdays);

			if @recycleselect<>'' and @recycleselect is not null THEN
					set @TMPSQL_TWO=concat(@TMPSQL_TWO, ' and recyclewheretableset.leadsid is not null  ');
			end if;
else
				if @recycleselect is not null and @recycleselect<>'' then

					set @sql=concat(' select tmpone.leadsid from  (',@tmpsql, ' ) as tmpone inner join ',@recycleselect,' on tmpone.leadsid=recyclewheretableset.leadsid  group by tmpone.leadsid ') ;
				ELSE
					set @sql=concat(' select leadsid from (',@tmpsql, ') as tmpone group by leadsid ') ;
				end if;

			set @TMPSQL_ONE=concat( ' select "系统","LOGPUBLICALLOCATELEADS",now(), ld_leads.leadsid,ld_leads.pool_id  from ld_leads inner join ( ',@sql,' ) as lingdangtmp  on  lingdangtmp.leadsid=ld_leads.leadsid ') ;
			set @TMPSQL_LOG_ONE=concat( ' select "系统","LOGPUBLICALLOCATELEADS",now(), ld_leads.leadsid,ld_leads.pool_id,ld_leads.smownerid,"',tmp_grammeid,'" as log_grammeid  from ld_leads inner join ( ',@sql,' ) as lingdangtmp  on  lingdangtmp.leadsid=ld_leads.leadsid ') ;
			set @TMPSQL_TWO=concat(' where ld_leads.deleted=0 and( ld_leads.publicaccount=2 or ld_leads.publicaccount=3) and ld_leads.pool_id = ',tmp_pool_id);

end if;
			set @TMPSQL_LOG_TWO = concat(@TMPSQL_LOG_ONE,@TMPSQL_TWO);
			set @TMPSQL_TWO = concat(@TMPSQL_ONE,@TMPSQL_TWO);
	   set @TMPSQL_THREE=concat('insert into ld_logpublicleads(username,operation,opdate,leadsid,pool_id,old_smownerid,programmeid) ',@TMPSQL_LOG_TWO);

 prepare stmt from @TMPSQL_THREE;
 execute stmt;
 deallocate prepare stmt;

set @tmp_namelink='\'<a style="display: initial;" doubleclick="yes" onclick="ListReferenceLinkClick(ld(this),event)" referencemodule="Leads" referencerecord="\',ld_leads.leadsid,\'">\',ld_leads.accountname,\'</a>\'';
    if var_condition='or'  then
			 set @TMPSQL_ONE=concat( ' select "complete" as type, GROUP_CONCAT(',@tmp_namelink,' separator "<br>")as accountnames,count(ld_leads.leadsid)  as totalaccounts,ld_leads.smownerid from    ld_leads left join ( ',@sql,' ) as lingdangtmp  on  lingdangtmp.leadsid=ld_leads.leadsid ') ;
		  if @recycleselect<>'' and @recycleselect is not null THEN
				set @TMPSQL_ONE=concat(@TMPSQL_ONE,' left join ',@recycleselect,' on recyclewheretableset.leadsid=ld_leads.leadsid ');
end if;
			set @TMPSQL_TWO=concat(@TMPSQL_ONE,' where ld_leads.deleted=0 and( ld_leads.publicaccount=2 or ld_leads.publicaccount=3)  ');
		  set @TMPSQL_TWO=concat(@TMPSQL_TWO, ' and lingdangtmp.leadsid is null  and datediff(curdate(),ld_leads.allocatedate)>',@maxdays);
		   if @recycleselect<>'' and @recycleselect is not null THEN
					set @TMPSQL_TWO=concat(@TMPSQL_TWO, ' and recyclewheretableset.leadsid is not null ');
end if;
		 set @TMPSQL_TWO=concat(@TMPSQL_TWO," group by ld_leads.smownerid ");
else
			set @TMPSQL_ONE=concat( ' select "complete" as type, GROUP_CONCAT(',@tmp_namelink,' separator "<br>")as accountnames,count(ld_leads.leadsid)  as totalaccounts,ld_leads.smownerid from    ld_leads  inner join ( ',@sql,' ) as lingdangtmp  on  lingdangtmp.leadsid=ld_leads.leadsid ') ;
		   set @TMPSQL_TWO=concat(@TMPSQL_ONE,' where ld_leads.deleted=0  and( ld_leads.publicaccount=2 or ld_leads.publicaccount=3)   group by ld_leads.smownerid    ');
end if;
delete from ld_publicleads_remindtableview ;

set @tmpthree=concat(" insert into ld_publicleads_remindtableview(type,names,totalleads,smownerid )  ", @TMPSQL_TWO);
prepare stmt from @tmpthree;
execute stmt;
deallocate prepare stmt;

call crm_publicleads_recoveryreminds();

if var_condition='or'  then

			 set @TMPSQL_ONE=concat( ' update  ld_leads left join ( ',@sql,' ) as lingdangtmp  on  lingdangtmp.leadsid=ld_leads.leadsid ');
		  if @recycleselect<>'' and @recycleselect is not null THEN
				set @TMPSQL_ONE=concat(@TMPSQL_ONE,' left join ',@recycleselect,' on recyclewheretableset.leadsid=ld_leads.leadsid ');
end if;
			set @TMPSQL_ONE=concat( @TMPSQL_ONE,' set ld_leads.publicaccount=1 ,protectdate=null ,allocatedate=null') ;
			 if @allotaccount>0 THEN
					set @TMPSQL_ONE=concat(@TMPSQL_ONE,",smownerid=",@allotaccount);
end if;
		   set @TMPSQL_TWO=concat(@TMPSQL_ONE,' where ld_leads.deleted=0 and( ld_leads.publicaccount=2 or ld_leads.publicaccount=3) and ld_leads.pool_id = ',tmp_pool_id);
		   set @TMPSQL_TWO=concat(@TMPSQL_TWO, ' and lingdangtmp.leadsid is null and datediff(curdate(),ld_leads.allocatedate)>',@maxdays);
				if @recycleselect<>'' and @recycleselect is not null THEN
						set @TMPSQL_TWO=concat(@TMPSQL_TWO, ' and recyclewheretableset.leadsid is not null  ');
end if;
ELSE

			  set @TMPSQL_ONE=concat( ' update  ld_leads inner join ( ',@sql,' ) as lingdangtmp  on  lingdangtmp.leadsid=ld_leads.leadsid set ld_leads.publicaccount=1 ,protectdate=null ,allocatedate=null') ;
		    if @allotaccount>0 THEN
					set @TMPSQL_ONE=concat(@TMPSQL_ONE,",smownerid=",@allotaccount);
				end if;
				if target_pool_id >0 then
					set @TMPSQL_ONE=concat(@TMPSQL_ONE,",ld_leads.pool_id=",target_pool_id);
				end if;
		  	set @TMPSQL_TWO=concat(@TMPSQL_ONE,' where ld_leads.deleted=0 and( ld_leads.publicaccount=2 or ld_leads.publicaccount=3) and ld_leads.pool_id = ',tmp_pool_id);
end if;

prepare stmt from @TMPSQL_TWO;
execute stmt;
deallocate prepare stmt;

end if;
end ;;
