DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `splitstr` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `splitstr`(s_str varchar(128), s_split varchar(3))
begin

	drop table if exists splitstrlist;
	create temporary table splitstrlist( str varchar(100));
  set @i = length(s_str) - length(replace(s_str,s_split,''));  
  set @left_str = s_str;
  while @i>0                
  do
  set @sub_str = substr(@left_str,1,instr(@left_str,s_split)-1);            
  set @left_str = substr(@left_str,length(@sub_str)+length(s_split)+1);     
  set @n = trim(@sub_str);
  insert into splitstrlist(str) values(@n);
  set @i = @i - 1;
  end while;
  set @n = trim(@left_str);
  insert into splitstrlist(str) values(@n);
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `task_accounts_remind_lastservicedate` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `task_accounts_remind_lastservicedate`(
)
BEGIN


	declare tmp_accountid int(19) default 0;
	declare tmp_accountname varchar(255) default NULL;
	declare tmp_date date default NULL;
	declare tmp_recieverid int(19) default 0;
	declare tmp_days int(19) default 0;

	declare cur1 cursor for SELECT
								accountid,
								accountname,
								lastservicedate,
								smownerid,
								DATEDIFF(lastservicedate,CURDATE()) AS days
							FROM ld_account
							WHERE deleted=0
								AND lastservicedate BETWEEN DATE_SUB(CURDATE(),INTERVAL 37 DAY) AND DATE_ADD(CURDATE(),INTERVAL 30 DAY);

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_accountid = NULL;

	OPEN cur1;
	Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;
	while(tmp_accountid is not null) DO
		IF tmp_days<=-30 THEN
			SET @remind_type='自动任务之服务过期提醒';
			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab='Accounts' and content like '自动任务之服务过期提醒%') THEN
				set @content=concat(@remind_type,'，您的客户',tmp_accountname,'服务已经过期',abs(tmp_days),'天（',tmp_date,'），请及时跟进！');

				set @maxid=0;
				select max(crmid) into @maxid from ld_crmentity;
				insert into ld_crmentity(crmid,setype)
				select @maxid+1,'Reminds';
				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
				select @maxid+1,@content,now(),tmp_recieverid,'未读',tmp_accountid,'Accounts',0,0,0,1,1,1,now(),now(),null,0;

				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		ELSEIF tmp_days=0 AND tmp_days>=-7 THEN
			SET @remind_type='自动任务之服务到期提醒';
			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab='Accounts' and content like '自动任务之服务到期提醒%') THEN
				set @content=concat(@remind_type,'，您的客户',tmp_accountname,'服务已经到期（',tmp_date,'），请及时跟进！');

				set @maxid=0;
				select max(crmid) into @maxid from ld_crmentity;
				insert into ld_crmentity(crmid,setype)
				select @maxid+1,'Reminds';
				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
				select @maxid+1,@content,now(),tmp_recieverid,'未读',tmp_accountid,'Accounts',0,0,0,1,1,1,now(),now(),null,0;

				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		ELSEIF tmp_days>=23 AND tmp_days<=30 THEN
			SET @remind_type='自动任务之服务即将到期提醒';

			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab='Accounts' and content like '自动任务之服务即将到期提醒%') THEN

				set @content=concat(@remind_type,'，您的客户',tmp_accountname,'还有',abs(tmp_days),'天（',tmp_date,'）即将到期，请及时跟进！');
				set @maxid=0;
				select max(crmid) into @maxid from ld_crmentity;
				insert into ld_crmentity(crmid,setype)
				select @maxid+1,'Reminds';
				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
				select @maxid+1,@content,now(),tmp_recieverid,'未读',tmp_accountid,'Accounts',0,0,0,1,1,1,now(),now(),null,0;

				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		END IF;

		Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;
	end while;
	close cur1;


end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `task_cooperativework_reminder` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `task_cooperativework_reminder`(
    tmp_reporttype VARCHAR(19),
    tmp_userid INT(11),
    tmp_eventdate datetime,
    tmp_nowtime datetime
        )
BEGIN
	DECLARE tmp_rule_range VARCHAR(19) DEFAULT '';
	DECLARE tmp_rule_value VARCHAR(19) DEFAULT '';
	DECLARE tmp_remind_num INT(11) DEFAULT '';
	DECLARE tmp_deadline_date VARCHAR(19) DEFAULT '';
	DECLARE tmp_remind_time time DEFAULT '';
	DECLARE tmp_first_value INT(11) DEFAULT '';
	DECLARE tmp_second_value INT(11) DEFAULT '';
	DECLARE tmp_third_value INT(11) DEFAULT '';

	DECLARE MYCUSOR CURSOR FOR
SELECT rule_range,rule_value,remind_num,deadline_date,remind_time,`first_value`,second_value,third_value
FROM ld_workreport_rulesettings WHERE type = tmp_reporttype AND `status` = 'yes' and remind_num >0 ORDER BY sequence;

DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_userid = NULL;










	SET @event_minutes = '10';

OPEN MYCUSOR;
FETCH MYCUSOR INTO tmp_rule_range,tmp_rule_value,tmp_remind_num,tmp_deadline_date,tmp_remind_time,tmp_first_value,tmp_second_value,tmp_third_value;
WHILE(tmp_userid IS NOT NULL) DO
			IF tmp_rule_range = 'all' THEN SET @remind_status='yes';
			ELSEIF tmp_rule_range = 'user' AND FIND_IN_SET(tmp_userid,tmp_rule_value)
				THEN SET @remind_status='yes';
			ELSEIF tmp_rule_range = 'group' AND
								tmp_userid IN (SELECT GROUP_CONCAT(userid SEPARATOR ',') AS userid_str FROM ld_users2group WHERE groupid IN (tmp_rule_value))
								THEN SET @remind_status='yes';
			ELSEIF tmp_rule_range = 'role' AND EXISTS(SELECT 1 from ld_users where id=tmp_userid and profileid in (tmp_rule_value))
								THEN SET @remind_status='yes';
ELSE SET @remind_status='no';
END IF;

			IF @remind_status = 'yes' AND tmp_remind_num > 0 THEN
					IF tmp_remind_num > 0 THEN
						
						SET @first_remind_time = CASE
									WHEN tmp_reporttype = 'day' THEN DATE_SUB(tmp_remind_time, INTERVAL (60 * tmp_first_value) MINUTE)
									ELSE tmp_remind_time END;
						SET @first_end_time = CASE
									WHEN tmp_reporttype = 'day' THEN DATE_ADD(tmp_remind_time, INTERVAL (60 * tmp_first_value + @event_minutes + 2) MINUTE)
									ELSE DATE_ADD(tmp_remind_time, INTERVAL @event_minutes + 2 MINUTE) END;
						SET @deadline_date = CONVERT(tmp_deadline_date, DECIMAL);
						
						SET @first_date = CASE
									WHEN tmp_reporttype = 'day' THEN CURDATE()
									WHEN tmp_reporttype = 'week' THEN CAST(tmp_deadline_date AS DECIMAL) - CAST(tmp_first_value AS DECIMAL)
									WHEN tmp_reporttype = 'month' THEN
											CASE
											WHEN @deadline_date >=20 AND @deadline_date <=28
												THEN DATE_SUB(STR_TO_DATE(CONCAT(DATE_FORMAT(CURDATE(), '%Y-%m'), '-', @deadline_date), '%Y-%m-%d'),INTERVAL tmp_first_value DAY)
											WHEN @deadline_date = 40
												THEN DATE_SUB(LAST_DAY(CURDATE()),INTERVAL tmp_first_value DAY)
											WHEN @deadline_date >= 1 AND @deadline_date <= 5
												THEN DATE_SUB(DATE_FORMAT(CURDATE() ,CONCAT('%Y-%m-0',@deadline_date)),INTERVAL tmp_first_value DAY)
END
END;
						
							IF (tmp_reporttype = 'day' OR tmp_reporttype = 'month') THEN
								SET @first_remind_datetime = STR_TO_DATE(CONCAT(@first_date, ' ', @first_remind_time), '%Y-%m-%d %H:%i:%s');
								SET @first_end_datetime = STR_TO_DATE(CONCAT(@first_date, ' ', @first_end_time), '%Y-%m-%d %H:%i:%s');
								IF tmp_eventdate < @first_remind_datetime AND tmp_nowtime >= @first_remind_datetime AND tmp_nowtime < @first_end_datetime
									THEN
										IF tmp_reporttype = 'day' THEN SET @content = CONCAT('日志提交提醒：您该提交日志啦，还有',tmp_first_value,'个小时就到提交期限哦');
										ELSEIF tmp_reporttype = 'month' THEN SET @content = CONCAT('月计划提交提醒：您该提交月计划啦，还有',tmp_first_value,'天就到提交期限哦');
END IF;
CALL ldcrm_add_reminder_havetype(@content,tmp_userid,'CooperativeWork',0,'WorkReportRemind');
END IF;
							ELSEIF tmp_reporttype = 'week' AND DAYOFWEEK(CURDATE()) = @first_date THEN
								SET @first_remind_datetime = STR_TO_DATE(CONCAT(DATE_FORMAT(tmp_nowtime,"%Y-%m-%d"), ' ', @first_remind_time), '%Y-%m-%d %H:%i:%s');
								SET @first_end_datetime = STR_TO_DATE(CONCAT(DATE_FORMAT(tmp_nowtime,"%Y-%m-%d"), ' ', @first_end_time), '%Y-%m-%d %H:%i:%s');
								IF tmp_eventdate < @first_remind_datetime AND tmp_nowtime >= @first_remind_datetime AND tmp_nowtime< @first_end_datetime
									THEN SET @content = CONCAT('周计划提交提醒：您该提交周计划啦，还有',tmp_first_value,'天就到提交期限哦');
CALL ldcrm_add_reminder_havetype(@content,tmp_userid,'CooperativeWork',0,'WorkReportRemind');
END IF;
END IF;
END IF;

					IF tmp_remind_num > 1 THEN
						
						SET @second_remind_time = CASE
									WHEN tmp_reporttype = 'day' THEN DATE_SUB(tmp_remind_time, INTERVAL (60 * tmp_second_value) MINUTE)
									ELSE tmp_remind_time END;
						SET @second_end_time = CASE
									WHEN tmp_reporttype = 'day' THEN DATE_ADD(tmp_remind_time, INTERVAL (60 * tmp_second_value +  @event_minutes + 2) MINUTE)
									ELSE DATE_ADD(tmp_remind_time, INTERVAL @event_minutes + 2 MINUTE) END;
						SET @deadline_date = CONVERT(tmp_deadline_date, DECIMAL);
						
						SET @second_date = CASE
									WHEN tmp_reporttype = 'day' THEN CURDATE()
									WHEN tmp_reporttype = 'week' THEN CAST(tmp_deadline_date AS DECIMAL) - CAST(tmp_second_value AS DECIMAL)
									WHEN tmp_reporttype = 'month' THEN
											CASE
											WHEN @deadline_date >=20 AND @deadline_date <=28
												THEN DATE_SUB(STR_TO_DATE(CONCAT(DATE_FORMAT(CURDATE(), '%Y-%m'), '-', @deadline_date), '%Y-%m-%d'),INTERVAL tmp_second_value DAY)
											WHEN @deadline_date = 40
												THEN DATE_SUB(LAST_DAY(CURDATE()),INTERVAL tmp_second_value DAY)
											WHEN @deadline_date >= 1 AND @deadline_date <= 5
												THEN DATE_SUB(DATE_FORMAT(CURDATE() ,CONCAT('%Y-%m-0',@deadline_date)),INTERVAL tmp_second_value DAY)
END
END;
						
						IF (tmp_reporttype = 'day' OR tmp_reporttype = 'month') THEN
								SET @second_remind_datetime = STR_TO_DATE(CONCAT(@second_date, ' ', @second_remind_time), '%Y-%m-%d %H:%i:%s');
								SET @second_end_datetime = STR_TO_DATE(CONCAT(@second_date, ' ', @second_end_time), '%Y-%m-%d %H:%i:%s');
								IF tmp_eventdate < @second_remind_datetime AND tmp_nowtime >= @second_remind_datetime AND tmp_nowtime < @second_end_datetime
									THEN
										IF tmp_reporttype = 'day' THEN SET @content = CONCAT('日志提交提醒：您该提交日志啦，还有',tmp_second_value,'个小时就到提交期限哦');
										ELSEIF tmp_reporttype = 'month' THEN SET @content = CONCAT('月计划提交提醒：您该提交月计划啦，还有',tmp_second_value,'天就到提交期限哦');
END IF;
CALL ldcrm_add_reminder_havetype(@content,tmp_userid,'CooperativeWork',0,'WorkReportRemind');
END IF;
							ELSEIF tmp_reporttype = 'week' AND DAYOFWEEK(CURDATE()) = @second_date THEN
								SET @second_remind_datetime = STR_TO_DATE(CONCAT(DATE_FORMAT(tmp_nowtime,"%Y-%m-%d"), ' ', @second_remind_time), '%Y-%m-%d %H:%i:%s');
								SET @second_end_datetime = STR_TO_DATE(CONCAT(DATE_FORMAT(tmp_nowtime,"%Y-%m-%d"), ' ', @second_end_time), '%Y-%m-%d %H:%i:%s');
								IF tmp_eventdate < @second_remind_datetime AND tmp_nowtime >= @second_remind_datetime AND tmp_nowtime< @second_end_datetime
									THEN SET @content = CONCAT('周计划提交提醒：您该提交周计划啦，还有',tmp_second_value,'天就到提交期限哦');
CALL ldcrm_add_reminder_havetype(@content,tmp_userid,'CooperativeWork',0,'WorkReportRemind');
END IF;
END IF;

END IF;

					IF tmp_remind_num > 2 THEN
						
						SET @third_remind_time = CASE
									WHEN tmp_reporttype = 'day' THEN DATE_SUB(tmp_remind_time, INTERVAL (60 * tmp_third_value ) MINUTE)
									ELSE tmp_remind_time END;
						SET @third_end_time = CASE
									WHEN tmp_reporttype = 'day' THEN DATE_ADD(tmp_remind_time, INTERVAL (60 * tmp_third_value +  @event_minutes + 2 ) MINUTE)
									ELSE DATE_ADD(tmp_remind_time, INTERVAL @event_minutes + 2 MINUTE) END;
						SET @deadline_date = CONVERT(tmp_deadline_date, DECIMAL);
						
						SET @third_date = CASE
									WHEN tmp_reporttype = 'day' THEN CURDATE()
									WHEN tmp_reporttype = 'week' THEN CAST(tmp_deadline_date AS DECIMAL) - CAST(tmp_third_value AS DECIMAL)
									WHEN tmp_reporttype = 'month' THEN
											CASE
											WHEN @deadline_date >=20 AND @deadline_date <=28
												THEN DATE_SUB(STR_TO_DATE(CONCAT(DATE_FORMAT(CURDATE(), '%Y-%m'), '-', @deadline_date), '%Y-%m-%d'),INTERVAL tmp_third_value DAY)
											WHEN @deadline_date = 40
												THEN DATE_SUB(LAST_DAY(CURDATE()),INTERVAL tmp_third_value DAY)
											WHEN @deadline_date >= 1 AND @deadline_date <= 5
												THEN DATE_SUB(DATE_FORMAT(CURDATE() ,CONCAT('%Y-%m-0',@deadline_date)),INTERVAL tmp_third_value DAY)
END
END;
						
						IF (tmp_reporttype = 'day' OR tmp_reporttype = 'month') THEN
								SET @third_remind_datetime = STR_TO_DATE(CONCAT(@third_date, ' ', @third_remind_time), '%Y-%m-%d %H:%i:%s');
								SET @third_end_datetime = STR_TO_DATE(CONCAT(@third_date, ' ', @third_end_time), '%Y-%m-%d %H:%i:%s');
								IF tmp_eventdate < @third_remind_datetime AND tmp_nowtime >= @third_remind_datetime AND tmp_nowtime < @third_end_datetime
									THEN
										IF tmp_reporttype = 'day' THEN SET @content = CONCAT('日志提交提醒：您该提交日志啦，还有',tmp_third_value,'个小时就到提交期限哦');
										ELSEIF tmp_reporttype = 'month' THEN SET @content = CONCAT('月计划提交提醒：您该提交月计划啦，还有',tmp_third_value,'天就到提交期限哦');
END IF;
CALL ldcrm_add_reminder_havetype(@content,tmp_userid,'CooperativeWork',0,'WorkReportRemind');
END IF;
							ELSEIF tmp_reporttype = 'week' AND DAYOFWEEK(CURDATE()) = @third_date THEN
								SET @third_remind_datetime = STR_TO_DATE(CONCAT(DATE_FORMAT(tmp_nowtime,"%Y-%m-%d"), ' ', @third_remind_time), '%Y-%m-%d %H:%i:%s');
								SET @third_end_datetime = STR_TO_DATE(CONCAT(DATE_FORMAT(tmp_nowtime,"%Y-%m-%d"), ' ', @third_end_time), '%Y-%m-%d %H:%i:%s');
								IF tmp_eventdate < @third_remind_datetime AND tmp_nowtime >= @third_remind_datetime AND tmp_nowtime< @third_end_datetime
									THEN SET @content = CONCAT('周计划提交提醒：您该提交周计划啦，还有',tmp_third_value,'天就到提交期限哦');
CALL ldcrm_add_reminder_havetype(@content,tmp_userid,'CooperativeWork',0,'WorkReportRemind');
END IF;
END IF;

END IF;

					SET tmp_userid = NULL;
END IF;

FETCH MYCUSOR INTO tmp_rule_range,tmp_rule_value,tmp_remind_num,tmp_deadline_date,tmp_remind_time,tmp_first_value,tmp_second_value,tmp_third_value;
END WHILE ;
CLOSE MYCUSOR;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `task_cooperativework_reminder_exec` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `task_cooperativework_reminder_exec`(
    tmp_reporttype VARCHAR(19)
)
BEGIN
	DECLARE tmp_userid INT DEFAULT 0;
	DECLARE MYCUSOR CURSOR FOR
SELECT DISTINCT a.id FROM ld_users a
                              LEFT JOIN ld_profile2standardpermissions c ON c.profileid=a.profileid
                              LEFT JOIN ld_tab d ON d.tabid=c.tabid
WHERE (d.`name`='CooperativeWork' AND permissions=0 AND d.presence in(0,2) AND a.`status`='Active' )
   OR (a.is_admin='on' AND a.`status`='Active');
DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_userid = NULL;

	SET @eventdatetime = (SELECT eventdate from ld_sys_event where type = CONCAT('task_cooperativework',tmp_reporttype,'_eventreminder'));
	SET @nowdatetime = NOW();
	SET @daytime = DAY(@nowdatetime);

	IF NOT EXISTS (SELECT 1 FROM ld_module_setting_byuser WHERE modulename = 'WorkTemplateRule' AND label = tmp_reporttype AND content = 'no') AND
		 EXISTS (SELECT 1 FROM ld_workreport_rulesettings WHERE type = tmp_reporttype AND `status` = 'yes' LIMIT 1 ) THEN
				OPEN MYCUSOR;
FETCH MYCUSOR INTO tmp_userid;
WHILE(tmp_userid IS NOT NULL) DO
					
					SET @remind_status = CASE
							WHEN tmp_reporttype = 'day'
									 AND NOT EXISTS(SELECT 1 FROM ld_workreport WHERE  DATE_FORMAT(createdtime,"%Y-%m-%d")=CURDATE() AND smcreatorid=tmp_userid and type=1)
							THEN 'yes'
							WHEN tmp_reporttype = 'week'
									 AND NOT EXISTS(SELECT 1 FROM  ld_workreport where createdtime BETWEEN date_sub(curdate(),INTERVAL WEEKDAY(curdate()) + 0 DAY)
									 AND date_sub(curdate(),INTERVAL WEEKDAY(curdate()) - 6 DAY) AND type=2 AND smcreatorid=tmp_userid)
							THEN 'yes'
							WHEN tmp_reporttype = 'month' AND (@daytime <= 5 OR @daytime >= 20)
									 AND NOT EXISTS(SELECT 1 FROM ld_workreport WHERE DATE_FORMAT(createdtime,"%Y-%m")=DATE_FORMAT(CURDATE(),"%Y-%m")  AND smcreatorid=tmp_userid and type=3)
							THEN 'yes'
							ELSE 'no' END;

					IF @remind_status = 'yes' THEN
						CALL task_cooperativework_reminder(tmp_reporttype,tmp_userid,@eventdatetime,@nowdatetime);
END IF;
FETCH MYCUSOR INTO tmp_userid;
END WHILE;
CLOSE MYCUSOR;
END IF;
UPDATE ld_sys_event set eventdate = NOW() where type = CONCAT('task_cooperativework',tmp_reporttype,'_eventreminder');
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `task_dailyreport_reminder` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `task_dailyreport_reminder`(
)
BEGIN
	
	DECLARE tmp_id INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR
		SELECT DISTINCT
			a.id
		FROM ld_users a
		LEFT JOIN ld_profile2standardpermissions c ON c.profileid=a.profileid
		LEFT JOIN ld_tab d ON d.tabid=c.tabid
		WHERE d.`name`='ReportLog'
			AND permissions=0
			AND a.`status`='Active';

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	IF EXISTS (SELECT 1 FROM ld_workremindset WHERE dailyreminddate LIKE '%:%') AND NOT EXISTS (SELECT 1 FROM ld_sys_event WHERE eventdate>CURDATE() AND type='task_dailyreport_reminder') THEN
		SET @remind='不提醒';
		SELECT IFNULL(dailyreminddate,'不提醒') INTO @remind FROM ld_workremindset LIMIT 1;
		
		SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '日报提交提醒：%' AND DATE_FORMAT(date_time,'%Y-%m-%d')=CURDATE();

		IF @remind<>'不提醒' AND WEEKDAY(NOW())<5 AND @cnt=0 AND DATE_FORMAT(DATE_ADD(NOW(),INTERVAL 1 HOUR),'%H:%i')>=@remind AND DATE_FORMAT(NOW(),'%H:%i')<=@remind THEN
			OPEN Mycur;
			FETCH Mycur INTO tmp_id;
			WHILE (tmp_id IS NOT NULL) DO
				IF NOT EXISTS (SELECT 1 FROM ld_dailyreport WHERE startdate=CURDATE() AND dstatus=1 AND smcreatorid=tmp_id) THEN
					SET @content=CONCAT('日报提交提醒：您该提交日报啦，还有一个小时就到提交期限哦');
					CALL ldcrm_add_reminder(@content,tmp_id,'ReportLog',0);
				END IF;
			FETCH Mycur INTO tmp_id;
			END WHILE;
			CLOSE Mycur;

			UPDATE ld_sys_event SET eventdate=NOW() WHERE type='task_dailyreport_reminder';
		END IF;
	END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `task_gonggao_reminder` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `task_gonggao_reminder`(
)
BEGIN
	
	DECLARE tmp_id INT(19) DEFAULT 0;
	DECLARE tmp_userid INT(19) DEFAULT 0;
	DECLARE tmp_content text DEFAULT '';

	DECLARE Mycur CURSOR FOR
		SELECT 
			a.publicannouncementid,
			b.userid
		FROM ld_publicannouncement a
		LEFT JOIN ld_publicannouncement_reminds b ON a.publicannouncementid=b.crmid
		WHERE a.deleted=0
			AND CURDATE() BETWEEN startdate AND enddate
			AND NOT EXISTS (SELECT 1 FROM ld_reminds WHERE related_to=a.publicannouncementid AND recieverid=b.userid AND content like '公告提醒：有新的公告，请及时关注！');

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	OPEN Mycur;
	FETCH Mycur INTO tmp_id,tmp_userid;
	WHILE (tmp_id IS NOT NULL) DO
		SET @content='公告提醒：有新的公告，请及时关注！';
		CALL ldcrm_add_reminder(@content,tmp_userid,'PublicAnnouncement',tmp_id);
		FETCH Mycur INTO tmp_id,tmp_userid;
	END WHILE;
	CLOSE Mycur;	
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `task_monthreport_reminder` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `task_monthreport_reminder`(
)
BEGIN
	
	DECLARE tmp_id INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR
		SELECT DISTINCT
			a.id
		FROM ld_users a
		LEFT JOIN ld_profile2standardpermissions c ON c.profileid=a.profileid
		LEFT JOIN ld_tab d ON d.tabid=c.tabid
		WHERE d.`name`='ReportLog'
			AND permissions=0
			AND a.`status`='Active';

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	SET @remind='不提醒';
	SELECT IFNULL(monthreminddate,'不提醒') INTO @remind FROM ld_workremindset LIMIT 1;

	IF @remind<>'不提醒' THEN
		IF @remind>=20 AND @remind<32 THEN
			SET @yue=MONTH(CURDATE());
			SET @do_remind=IF(DAY(CURDATE())>=@remind-2 AND DAY(CURDATE())<=@remind,1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE())-2 DAY);
			SET @days=@remind-DAY(CURDATE())+1;
		ELSEIF @remind=40 THEN
			SET @yue=MONTH(CURDATE());
			SET @do_remind=IF(DATE_ADD(CURDATE(),INTERVAL 2 DAY)>=LAST_DAY(CURDATE()),1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_SUB(LAST_DAY(CURDATE()),INTERVAL 2 DAY);	
			SET @days=DATEDIFF(LAST_DAY(CURDATE()),CURDATE())+1;
		ELSEIF @remind<=2 AND DAY(CURDATE())>=25 THEN
			SET @yue=MONTH(CURDATE());
			SET @do_remind=IF(CURDATE()>=DATE_ADD(LAST_DAY(CURDATE()),INTERVAL @remind-2 DAY),1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_ADD(LAST_DAY(CURDATE()),INTERVAL @remind-2 DAY);	
			SET @days=DATEDIFF(DATE_ADD(LAST_DAY(CURDATE()), INTERVAL @remind DAY),CURDATE())+1;
		ELSEIF @remind<=2 AND DAY(CURDATE()) IN (1,2) THEN
			SET @yue=MONTH(CURDATE())-1;
			SET @do_remind=IF(CURDATE()<=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE()) DAY),1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE())-2 DAY);	
			SET @days=DATEDIFF(DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE()) DAY),CURDATE())+1;
		ELSEIF @remind>=3 AND @remind<=5 THEN
			SET @yue=MONTH(CURDATE())-1;
			SET @do_remind=IF(CURDATE()>=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE())-2 DAY) AND CURDATE()<=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(curdate()) DAY),1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE())-2 DAY);
			SET @days=DATEDIFF(DATE_ADD(CURDATE(),INTERVAL @remind-DAY(curdate()) DAY),CURDATE())+1;
		ELSE 
				SET @do_remind=0;
		END IF;

		IF @do_remind=1 AND @cnt=0 THEN 
			OPEN Mycur;
			FETCH Mycur INTO tmp_id;
			WHILE (tmp_id IS NOT NULL) DO
				IF NOT EXISTS (SELECT 1 FROM ld_monthreport WHERE monthofyear=@yue AND `Status`=1 AND smcreatorid=tmp_id) THEN
					IF @days=1 THEN
						SET @content=CONCAT('月报提交提醒：您该提交月报啦，今天就是提交期限哦');
					ELSE
						SET @content=CONCAT('月报提交提醒：您该提交月报啦，还有',@days,'天就是提交期限哦');
					END IF;
					CALL ldcrm_add_reminder(@content,tmp_id,'ReportLog',0);
				END IF;
			FETCH Mycur INTO tmp_id;
			END WHILE;
			CLOSE Mycur;	
		END IF;
	END IF;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `task_servicecharge_remind_lastservicedate` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `task_servicecharge_remind_lastservicedate`(
)
BEGIN


	declare tmp_accountid int(19) default 0;
	declare tmp_accountname varchar(255) default NULL;
	declare tmp_date date default NULL;
	declare tmp_recieverid int(19) default 0;
	declare tmp_days int(19) default 0;

	declare cur1 cursor for SELECT
								accountid,
								accountname,
								lastservicedate,
								CASE WHEN servicecasher>0 THEN servicecasher ELSE 1 END AS servicecasher,
								DATEDIFF(lastservicedate,CURDATE()) AS days
							FROM ld_account
							WHERE deleted=0
								AND lastservicedate BETWEEN DATE_SUB(CURDATE(),INTERVAL 37 DAY) AND DATE_ADD(CURDATE(),INTERVAL 30 DAY);

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_accountid = NULL;

	OPEN cur1;
	Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;
	while(tmp_accountid is not null) DO
		IF tmp_days<=-30 THEN
			SET @remind_type='自动任务之服务过期提醒';
			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab='ServiceCharge' and content like '自动任务之服务过期提醒%') THEN
				set @content=concat(@remind_type,'，您的客户',tmp_accountname,'服务已经过期',abs(tmp_days),'天（',tmp_date,'），请及时跟进！');

				set @maxid=0;
				select max(crmid) into @maxid from ld_crmentity;
				insert into ld_crmentity(crmid,setype)
				select @maxid+1,'Reminds';
				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
				select @maxid+1,@content,now(),tmp_recieverid,'未读',tmp_accountid,'ServiceCharge',0,0,0,1,1,1,now(),now(),null,0;

				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		ELSEIF tmp_days=0 AND tmp_days>=-7 THEN
			SET @remind_type='自动任务之服务到期提醒';
			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab='ServiceCharge' and content like '自动任务之服务到期提醒%') THEN
				set @content=concat(@remind_type,'，您的客户',tmp_accountname,'服务已经到期（',tmp_date,'），请及时跟进！');

				set @maxid=0;
				select max(crmid) into @maxid from ld_crmentity;
				insert into ld_crmentity(crmid,setype)
				select @maxid+1,'Reminds';
				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
				select @maxid+1,@content,now(),tmp_recieverid,'未读',tmp_accountid,'ServiceCharge',0,0,0,1,1,1,now(),now(),null,0;

				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		ELSEIF tmp_days>=23 AND tmp_days<=30 THEN
			SET @remind_type='自动任务之服务即将到期提醒';

			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab='ServiceCharge' and content like '自动任务之服务即将到期提醒%') THEN

				set @content=concat(@remind_type,'，您的客户',tmp_accountname,'还有',abs(tmp_days),'天（',tmp_date,'）即将到期，请及时跟进！');
				set @maxid=0;
				select max(crmid) into @maxid from ld_crmentity;
				insert into ld_crmentity(crmid,setype)
				select @maxid+1,'Reminds';
				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
				select @maxid+1,@content,now(),tmp_recieverid,'未读',tmp_accountid,'ServiceCharge',0,0,0,1,1,1,now(),now(),null,0;

				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		END IF;

		Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;
	end while;
	close cur1;


end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `task_weekreport_reminder` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `task_weekreport_reminder`(
)
BEGIN
	
	DECLARE tmp_id INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR
		SELECT DISTINCT
			a.id
		FROM ld_users a
		LEFT JOIN ld_profile2standardpermissions c ON c.profileid=a.profileid
		LEFT JOIN ld_tab d ON d.tabid=c.tabid
		WHERE d.`name`='ReportLog'
			AND permissions=0
			AND a.`status`='Active';

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	SET @remind='不提醒';
	SELECT IFNULL(weekreminddate,'不提醒') INTO @remind FROM ld_workremindset LIMIT 1;

	SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '周报提交提醒：%' AND WEEK(date_time)=WEEK(CURDATE());

	IF @remind<>'不提醒' AND WEEKDAY(NOW())IN (@remind-2,@remind-1) AND @cnt=0 THEN
		OPEN Mycur;
		FETCH Mycur INTO tmp_id;
		WHILE (tmp_id IS NOT NULL) DO
			IF NOT EXISTS (SELECT 1 FROM ld_weekreport WHERE Weeksofyear=WEEK(CURDATE()) AND yearbol=YEAR(CURDATE()) AND `status`=1 AND smcreatorid=tmp_id) THEN
				IF WEEKDAY(NOW())=@remind-2 THEN
					SET @content=CONCAT('周报提交提醒：您该提交周报啦，明天是最后一天期限哦');
				ELSEIF WEEKDAY(CURDATE())=@remind-1 THEN
					SET @content=CONCAT('周报提交提醒：您该提交周报啦，今天是最后一天期限哦');
				END IF;
				CALL ldcrm_add_reminder(@content,tmp_id,'ReportLog',0);
			END IF;
		FETCH Mycur INTO tmp_id;
		END WHILE;
		CLOSE Mycur;	
	END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `taxamountreverseallproducttool` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `taxamountreverseallproducttool`()
BEGIN
	
	declare done  int  default 0;
 declare ttabid  int ;
	declare cur2 CURSOR FOR SELECT tabid    FROM  ld_producttoolfield  where columnname='tax_amount' group by tabid ;
	declare continue handler  for not   found  SET done =1;
select deploy_value into @deploy_value from ld_systems_deploy where deploy_type=140;
	OPEN cur2;
	Fetch cur2 into ttabid;

 	loop1: while  done<>1 DO
		
			call reverseproducttooldiscount(ttabid);
		  call reverseproducttoolprice(ttabid);
		  Fetch cur2 into ttabid;
	end while loop1;
	close cur2;
	 update ld_reverseformula inner join ld_producttoolfield  on ld_producttoolfield.producttoolfieldid=ld_reverseformula.parentid
    set reversefieldtype='listprice'
    where reversetable='ld_producttoolfield' and reversefieldtype is null and ld_producttoolfield.columnname='tax_amount' ;
	
  update ld_reverseformula set activatestatus='no';
  set @sql=concat('update ld_reverseformula set activatestatus="yes" where  reversefieldtype="',@deploy_value,'"');

	PREPARE altersql from @sql;
	execute altersql;
  DEALLOCATE PREPARE altersql;
    
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `update_account_lastcontactuser` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `update_account_lastcontactuser`(
)
BEGIN
	
	
		declare tmp_accountid int;
		declare tmp_smownerid int;

		declare cur1 CURSOR FOR select b.accountid,a.smownerid
														from (
																select 
																accountid,smownerid,max(contactdate) as contactdate
																from ld_contactrecords 
																where deleted=0 and accountid>0 
																GROUP BY accountid
																order by accountid, contactdate DESC) a 
														INNER JOIN ld_account b on a.accountid=b.accountid
														where b.lastcontactuser=0 and a.smownerid>0;

		DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_accountid = NULL;
	
		OPEN cur1;
		Fetch cur1 into tmp_accountid,tmp_smownerid;
		while(tmp_accountid is not null) DO
				update ld_account set lastcontactuser=tmp_smownerid where lastcontactuser=0 and accountid=tmp_accountid;
		Fetch cur1 into tmp_accountid,tmp_smownerid;
		end while;
		close cur1;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `update_account_lastservicedate` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `update_account_lastservicedate`(
)
begin

	declare tmp_accountid int default 0;

	declare cur2 CURSOR FOR select accountid from ld_account;
	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_accountid = NULL;
	
	open cur2;
	fetch cur2 into tmp_accountid;
	while(tmp_accountid is not null) DO
		set @service_enddate=NULL;
		select max(service_enddate) into @service_enddate from ld_maxservicedate where accountid=tmp_accountid;
		
		IF @service_enddate is not NULL THEN
			update ld_account set lastservicedate=@service_enddate where accountid=tmp_accountid;
		ELSE
			set @signed_data=NULL;
			SELECT max(signed_data) into @signed_data FROM ld_salesorder WHERE accountid=tmp_accountid and ifnull(sostatus,'')<>'已作废' and IFNULL(approvestatus,'')<>'已拒绝';
			IF @signed_data is not NULL THEN
				update ld_account set lastservicedate=@signed_data where accountid=tmp_accountid;
			ELSE
				update ld_account set lastservicedate=DATE_FORMAT(createdtime,'%Y-%m-%d') where accountid=tmp_accountid;
			END IF;
		END IF;

		Fetch cur2 into tmp_accountid;
	end while;
	close cur2;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
